/* ═══════════════════════════════════════════
   设计 Token —— 对齐 reference/DESIGN_NOTES.md
   ═══════════════════════════════════════════ */
:root {
  --bg: #EDF2FB;
  --ink: #33383F;
  --ink-2: #7A8290;
  --ink-3: #A9B1BD;
  --blue: #3D7BF7;
  --blue-soft: #E8F0FE;
  --line: #E3EAF4;
  --card: #FFFFFF;
  --radius-card: 12px;
  --radius-icon: 50%;
  --row-h: 62px;
  --time-col-w: 46px;
  --topbar-h: auto;
  --sat: env(safe-area-inset-top, 0px);
  --sab: env(safe-area-inset-bottom, 0px);

  /* 马卡龙课程色：底色 / 深一档横条与文字 */
  --c0-bg: #DCE8C5; --c0-ink: #6E8B3D; --c0-bar: #A9C97E;
  --c1-bg: #F8DFC4; --c1-ink: #B4763A; --c1-bar: #E8A96F;
  --c2-bg: #DDD6F5; --c2-ink: #6C5BC4; --c2-bar: #9D8FE0;
  --c3-bg: #F9D9DC; --c3-ink: #C05E6E; --c3-bar: #E89AA6;
  --c4-bg: #FAE7BD; --c4-ink: #A8842E; --c4-bar: #E5C25A;
  --c5-bg: #C9E4F6; --c5-ink: #3E7CA8; --c5-bar: #7FB8E0;
  --c6-bg: #CDE8DC; --c6-ink: #3E8E6C; --c6-bar: #7FC4A4;
  --c7-bg: #D6DAEC; --c7-ink: #5A6699; --c7-bar: #96A0CC;
}

* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
[hidden] { display: none !important; }
html { height: 100%; }
body {
  height: 100%;
  background: var(--bg);
  color: var(--ink);
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Helvetica Neue", "Microsoft YaHei", sans-serif;
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}
button { font-family: inherit; border: none; background: none; color: inherit; cursor: pointer; }

#app { height: 100%; display: flex; flex-direction: column; }

/* ═══ 表头信息区 ═══ */
.topbar {
  display: flex; align-items: flex-start; justify-content: space-between;
  padding: calc(var(--sat) + 14px) 16px 6px;
}
.date-title { font-size: 22px; font-weight: 700; letter-spacing: .2px; color: #262B33; }
.week-line {
  display: inline-flex; align-items: center; gap: 7px;
  margin-top: 3px; padding: 2px 0; font-size: 13.5px; color: var(--ink-2);
}
.week-line .week-text b { color: var(--blue); font-weight: 600; }
.week-line:active { opacity: .6; }
.swap-ico { color: var(--ink-3); }
.topbar-actions { display: flex; gap: 8px; padding-top: 2px; }
.icon-btn {
  width: 32px; height: 32px; border-radius: var(--radius-icon);
  background: #E7EDF6; color: #4A525D;
  display: inline-flex; align-items: center; justify-content: center;
  transition: transform .12s ease, background .12s ease;
}
.icon-btn:active { transform: scale(.92); background: #DCE4F0; }

/* ═══ 星期表头行 ═══ */
.weekbar {
  display: grid;
  grid-template-columns: var(--time-col-w) repeat(7, 1fr);
  align-items: end;
  padding: 8px 6px 4px;
  user-select: none;
}
.wb-month {
  font-size: 13px; font-weight: 700; color: #4A525D; line-height: 1.05;
  padding-left: 8px; text-align: left;
}
.wb-month small { display: block; font-size: 9px; font-weight: 500; color: var(--ink-3); }
.wb-day { text-align: center; padding-bottom: 3px; }
.wb-day .wd { font-size: 11px; color: var(--ink-2); margin-bottom: 4px; }
.wb-day .dn {
  width: 26px; height: 26px; line-height: 26px; margin: 0 auto;
  font-size: 14px; font-weight: 500; color: #5D6672; border-radius: 50%;
}
.wb-day.weekend .wd, .wb-day.weekend .dn { color: var(--ink-3); }
.wb-day.today .wd { color: var(--blue); font-weight: 600; }
.wb-day.today .dn { background: var(--blue); color: #fff; font-weight: 600; }
.wb-day:not(.today) { cursor: pointer; }
.wb-day:not(.today):active .dn { background: #EAE7E0; }

/* 当前课表名入口 */
.sch-pill {
  align-self: flex-start;
  display: inline-flex; align-items: center; gap: 5px;
  margin: 0 0 2px 16px; padding: 4px 11px;
  background: #E7EDF6; border-radius: 20px;
  font-size: 11.5px; font-weight: 600; color: #5D6672;
  max-width: calc(100% - 32px);
}
.sch-pill span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sch-pill:active { background: #DCE4F0; }

/* 今日课程胶囊 */
.today-pill {
  align-self: flex-start;
  display: inline-flex; align-items: center; gap: 5px;
  margin: 2px 0 0 16px; padding: 5px 12px;
  background: var(--blue-soft); border-radius: 20px;
  font-size: 11.5px; font-weight: 600; color: var(--blue);
  max-width: calc(100% - 32px);
}
.today-pill span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.today-pill:active { filter: brightness(.96); }

/* 今日课程面板 */
.t-list { display: flex; flex-direction: column; gap: 9px; margin: 6px 0 4px; }
.t-row {
  display: flex; align-items: center; gap: 12px;
  background: #fff; border-radius: 13px; padding: 11px 13px;
  box-shadow: 0 1px 6px rgba(45,70,120,.08);
}
.t-row.active { box-shadow: inset 0 0 0 1.5px var(--blue), 0 1px 6px rgba(61,123,247,.15); }
.t-row.dim { opacity: .5; }
.t-time { text-align: center; flex: none; font-size: 14px; font-weight: 700; color: #33383F; line-height: 1.2; }
.t-time small { display: block; font-size: 10px; font-weight: 500; color: var(--ink-3); }
.t-main { flex: 1; min-width: 0; }
.t-name { font-size: 14.5px; font-weight: 600; color: #33383F; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.t-loc { font-size: 11px; color: var(--ink-2); margin-top: 2px; }
.t-badge {
  flex: none; font-size: 10px; font-weight: 600; line-height: 1;
  padding: 4px 8px; border-radius: 8px;
}
.t-badge.now { background: var(--blue); color: #fff; }
.t-badge.todo { background: #EAE7F9; color: #6C5BC4; }
.t-badge.done { background: #E7EDF6; color: var(--ink-2); }
.t-empty { text-align: center; padding: 26px 0; color: var(--ink-2); font-size: 13.5px; }

/* ═══ 课程网格 ═══ */
.grid-scroll { flex: 1; overflow-y: auto; -webkit-overflow-scrolling: touch; position: relative; }
.grid { display: flex; position: relative; padding: 2px 6px calc(var(--sab) + 16px); }
.time-col { width: var(--time-col-w); flex: none; position: relative; }
.time-cell { position: absolute; left: 0; right: 6px; text-align: center; }
.time-cell .tn { font-size: 15px; font-weight: 700; color: #414954; margin-bottom: 3px; }
.time-cell .tt { font-size: 9.5px; color: var(--ink-3); line-height: 1.35; }
.time-cell.now .tn {
  display: inline-block; width: 22px; height: 22px; line-height: 22px;
  background: var(--blue); color: #fff; border-radius: 50%; font-size: 13px;
  margin-bottom: 2px;
}
.time-cell.now .tt { display: block; font-size: 8.5px; line-height: 1.3; color: var(--blue); font-weight: 600; }

.days-grid { flex: 1; display: flex; position: relative; }
.day-col { flex: 1; position: relative; min-width: 0; }

/* 课程卡片：白卡 + 左侧彩条（Solyra 风） */
.course {
  position: absolute; left: 1.5px; right: 1.5px;
  border-radius: var(--radius-card);
  padding: 7px 6px 5px 9px;
  overflow: hidden;
  display: flex; flex-direction: column;
  user-select: none;
  background: var(--card);
  box-shadow: 0 2px 10px rgba(61, 90, 152, .08);
}
.course .bar {
  position: absolute; left: 0; top: 9px; bottom: 9px;
  width: 4px; border-radius: 0 3px 3px 0;
}
.course .cname {
  font-size: 11.5px; font-weight: 700; line-height: 1.28;
  color: var(--ink); word-break: break-all;
}
.course .cloc { font-size: 10px; line-height: 1.35; margin-top: 3px; word-break: break-all; color: var(--ink-2); }
.course .ctime { font-size: 9px; margin-top: auto; padding-top: 2px; opacity: .75; color: var(--ink-3); }

/* 状态修饰 */
.course.ghost { opacity: .5; background: transparent; box-shadow: inset 0 0 0 1.2px var(--line); }
.course.ghost .cname { font-weight: 600; color: var(--ink-2); }
.badge {
  align-self: flex-start;
  font-size: 8.5px; font-weight: 600; line-height: 1;
  padding: 2.5px 5px; border-radius: 6px; margin-bottom: 4px;
  white-space: nowrap;
}

/* ═══ 空状态 ═══ */
.empty-state {
  position: absolute; inset: 0;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; padding: 0 40px; gap: 6px;
}
.empty-ico { font-size: 40px; margin-bottom: 4px; }
.empty-title { font-size: 17px; font-weight: 700; color: #4A525D; }
.empty-hint { font-size: 12.5px; color: var(--ink-2); line-height: 1.7; }
.primary-btn {
  margin-top: 14px; padding: 10px 22px;
  background: var(--blue); color: #fff;
  font-size: 14px; font-weight: 600; border-radius: 20px;
}
.primary-btn:active { opacity: .85; }

/* ═══ 周次选择浮层 ═══ */
.week-picker {
  position: absolute; z-index: 40;
  left: 16px; top: 76px;
  max-height: 320px; overflow-y: auto;
  background: #fff; border-radius: 14px;
  box-shadow: 0 10px 40px rgba(40,60,100,.16);
  padding: 6px;
}
.wp-item {
  display: flex; align-items: center; gap: 6px;
  width: 100%; text-align: left;
  padding: 8px 14px; font-size: 13.5px; color: #3A414B; border-radius: 9px;
}
.wp-item small { color: var(--ink-3); font-size: 10.5px; margin-left: auto; }
.wp-item.active { background: var(--blue-soft); color: var(--blue); font-weight: 600; }
.wp-item:active { background: #E9EFF9; }

/* ═══ 底部面板（设置/课表管理） ═══ */
.sheet-mask {
  position: fixed; inset: 0; z-index: 50;
  background: rgba(25,35,55,.35);
  opacity: 0; transition: opacity .2s ease;
}
.sheet-mask.show { opacity: 1; }
.sheet {
  position: fixed; z-index: 51;
  left: 0; right: 0; bottom: 0;
  max-height: 78vh; overflow-y: auto;
  background: #F8FAFE;
  border-radius: 20px 20px 0 0;
  padding: 10px 18px calc(var(--sab) + 20px);
  transform: translateY(100%); transition: transform .24s cubic-bezier(.32,.72,.35,1);
}
.sheet.show { transform: translateY(0); }
.sheet-grip { width: 36px; height: 4.5px; border-radius: 3px; background: #D3DCE8; margin: 4px auto 14px; }
.sheet h2 { font-size: 17px; font-weight: 700; margin-bottom: 4px; }
.sheet .sub { font-size: 12px; color: var(--ink-2); margin-bottom: 12px; }

.sch-item {
  display: flex; align-items: center; gap: 12px;
  padding: 11px 12px; border-radius: 13px;
  transition: background .15s ease;
}
.sch-item:active { background: #F0EEE8; }
.sch-item.current { background: #fff; box-shadow: 0 1px 6px rgba(45,70,120,.08); }
.sch-swatch { width: 34px; height: 34px; border-radius: 9px; flex: none; display: flex; align-items: center; justify-content: center; font-size: 15px; font-weight: 700; }
.sch-meta { flex: 1; min-width: 0; }
.sch-name { font-size: 14.5px; font-weight: 600; color: #33383F; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sch-info { font-size: 11px; color: var(--ink-2); margin-top: 2px; }
.sch-acts { display: flex; gap: 2px; }
.sch-act { width: 30px; height: 30px; border-radius: 8px; display: inline-flex; align-items: center; justify-content: center; color: var(--ink-2); }
.sch-act:active { background: #E2E9F3; }
.sch-act.danger { color: #D66; }

.import-row {
  display: flex; gap: 10px; margin-top: 6px;
}
.import-row .primary-btn { flex: 1; margin-top: 0; }
.ghost-btn {
  flex: 1; margin-top: 6px; padding: 10px 22px;
  border: 1.5px solid #D3DCE8; color: #5D6672;
  font-size: 14px; font-weight: 600; border-radius: 20px; background: none;
}
.danger-btn {
  width: 100%; margin-top: 16px; padding: 11px;
  background: none; border: none; color: #D64545; font-size: 14.5px; font-weight: 600;
}

/* 开学日期设置 */
.sem-row {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12px 12px; background: #fff; border-radius: 13px; margin-top: 8px;
  box-shadow: 0 1px 6px rgba(45,70,120,.08);
}
.sem-row label { font-size: 13.5px; font-weight: 600; color: #33383F; }
.sem-row input {
  border: none; background: #EDF2FA; padding: 6px 10px; border-radius: 8px;
  font-family: inherit; font-size: 13px; color: #33383F;
}

/* ═══ 课程添加/编辑表单 ═══ */
.form { display: flex; flex-direction: column; gap: 6px; }
.f-label { font-size: 12px; font-weight: 600; color: var(--ink-2); margin-top: 8px; }
.f-input {
  width: 100%; padding: 10px 12px;
  border: 1.5px solid #D8E0EC; border-radius: 11px;
  background: #fff; font-family: inherit; font-size: 14.5px; color: #33383F;
  outline: none; -webkit-appearance: none; appearance: none;
}
.f-input:focus { border-color: var(--blue); }
select.f-input { width: auto; flex: 1; }
.f-row2 { display: flex; align-items: center; gap: 8px; }
.f-row2 .f-input { flex: 1; }
.f-sep { color: var(--ink-3); font-size: 12.5px; }
.chips { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 2px; }
.chip {
  padding: 7px 13px; border-radius: 17px;
  background: #fff; border: 1.5px solid #D8E0EC;
  font-size: 12.5px; font-weight: 600; color: #5D6672;
}
.chip.on { background: var(--blue-soft); border-color: var(--blue); color: var(--blue); }
.dot { width: 30px; height: 30px; border-radius: 50%; border: 2.5px solid transparent; }
.dot.on { border-color: var(--ink); transform: scale(1.08); }
.f-btns { display: flex; gap: 9px; margin-top: 16px; flex-wrap: wrap; }
.f-btns .wide { flex: 1; min-width: 110px; margin-top: 0; padding: 11px 10px; }
.danger-btn.slim { width: auto; flex: none; margin-top: 0; padding: 11px 16px; }

/* ═══ OCR 识别导入 ═══ */
.ocr-progress {
  position: fixed; inset: 0; z-index: 95;
  display: flex; align-items: center; justify-content: center;
  background: rgba(25,35,55,.45);
}
.ocr-card {
  background: #fff; border-radius: 16px; padding: 22px 26px;
  display: flex; flex-direction: column; align-items: center; gap: 12px;
  font-size: 14px; font-weight: 600; color: #33383F;
}
.spinner {
  width: 30px; height: 30px; border-radius: 50%;
  border: 3.5px solid #D8E0EC; border-top-color: var(--blue);
  animation: spin .8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
.ocr-sheet { max-height: 84vh; }
#ocrRows { display: flex; flex-direction: column; gap: 9px; margin: 6px 0 4px; }
.ocr-row {
  display: flex; align-items: flex-start; gap: 9px;
  background: #fff; border-radius: 13px; padding: 10px;
  box-shadow: 0 1px 6px rgba(45,70,120,.08);
}
.ocr-check { width: 17px; height: 17px; margin-top: 12px; accent-color: var(--blue); flex: none; }
.ocr-fields { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 6px; }
.ocr-line1 { display: flex; gap: 6px; }
.ocr-line1 .i-name { flex: 1.3; padding: 7px 9px; font-size: 13px; }
.ocr-line1 .i-loc { flex: 1; padding: 7px 9px; font-size: 13px; }
.ocr-line2 { display: flex; align-items: center; gap: 6px; }
.ocr-line2 .f-input { padding: 6px 7px; font-size: 12.5px; flex: 1; }

/* ═══ 设置面板折叠区段 ═══ */
details.sec {
  margin-top: 10px; background: #fff; border-radius: 13px;
  box-shadow: 0 1px 6px rgba(45,70,120,.08);
  overflow: hidden;
}
details.sec summary {
  list-style: none; cursor: pointer;
  padding: 13px 14px; font-size: 14px; font-weight: 600; color: #33383F;
  display: flex; align-items: center; justify-content: space-between;
}
details.sec summary::-webkit-details-marker { display: none; }
details.sec summary::after { content: '⌄'; color: var(--ink-3); font-size: 15px; transition: transform .15s; }
details.sec[open] summary::after { transform: rotate(180deg); }
details.sec[open] summary { border-bottom: 1px solid var(--line); }
.sec-body { padding: 12px 14px 14px; }
.bg-row { display: flex; align-items: center; gap: 9px; }
.bg-row input[type="color"] {
  width: 44px; height: 32px; border: none; border-radius: 8px; background: none; padding: 0; cursor: pointer;
}
.pedit-row { display: flex; align-items: center; gap: 7px; margin-bottom: 7px; }
.pedit-n { width: 22px; text-align: center; font-size: 12.5px; font-weight: 700; color: #4A525D; flex: none; }
.pedit-t {
  flex: 1; min-width: 0; border: 1.5px solid #D8E0EC; border-radius: 9px;
  background: #F5F8FD; padding: 6px 7px; font-family: inherit; font-size: 13px; color: #33383F;
}

/* ═══ Toast ═══ */
.toast {
  position: fixed; z-index: 90;
  left: 50%; bottom: calc(var(--sab) + 60px);
  transform: translateX(-50%) translateY(8px);
  max-width: 78vw;
  background: rgba(35,44,60,.94); color: #fff;
  font-size: 13px; line-height: 1.5;
  padding: 10px 16px; border-radius: 12px;
  opacity: 0; transition: opacity .2s ease, transform .2s ease;
  pointer-events: none;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.toast.ok::before { content: "✓ "; color: #9FE0B5; }
.toast.err::before { content: "✕ "; color: #FF9E9E; }

/* ═══ 拖拽遮罩 ═══ */
.drop-overlay {
  position: fixed; inset: 0; z-index: 99;
  background: rgba(61,123,247,.10);
  backdrop-filter: blur(2px);
  display: flex; align-items: center; justify-content: center;
}
.drop-box {
  border: 2.5px dashed var(--blue); color: var(--blue);
  background: #fff;
  font-size: 16px; font-weight: 700;
  padding: 26px 40px; border-radius: 18px;
}

/* ═══ 课程详情弹层 ═══ */
.course-pop {
  position: fixed; z-index: 60; inset: 0;
  display: flex; align-items: flex-end; justify-content: center;
  background: rgba(25,35,55,.28);
}
.course-pop .pop-card {
  width: 100%; max-width: 420px;
  background: #F8FAFE; border-radius: 20px 20px 0 0;
  padding: 20px 22px calc(var(--sab) + 24px);
}
.pop-card .p-name { font-size: 19px; font-weight: 700; color: #262B33; }
.pop-edit {
  margin-top: 16px; width: 100%; padding: 11px;
  background: var(--blue-soft); border-radius: 14px;
  font-size: 14.5px; font-weight: 600; color: var(--blue);
}
.pop-card .p-rows { margin-top: 12px; display: flex; flex-direction: column; gap: 9px; }
.pop-card .p-row { display: flex; font-size: 13.5px; }
.pop-card .p-k { width: 64px; color: var(--ink-2); flex: none; }
.pop-card .p-v { color: #33383F; font-weight: 500; }
.pop-close {
  margin-top: 18px; width: 100%; padding: 11px;
  background: #E2E9F3; border-radius: 14px;
  font-size: 14.5px; font-weight: 600; color: #4A525D;
}

/* ═══════════════════════════════════════════
   液态玻璃（Liquid Glass）—— 对齐 iOS 26 质感
   环境光斑背景 + backdrop-filter 折射 + 高光描边
   ═══════════════════════════════════════════ */
:root {
  --glass-blur: 22px;
  --glass-sat: 165%;
  --glass-bg: rgba(255, 255, 255, .50);
  --glass-bg-strong: rgba(255, 255, 255, .64);
  --glass-border: rgba(255, 255, 255, .55);
  --glass-inset: inset 0 1px 0 rgba(255, 255, 255, .55), inset 0 0 0 .5px rgba(255, 255, 255, .28);
  --glass-shadow: 0 8px 28px rgba(60, 64, 90, .12);
  --glass-sheen: linear-gradient(120deg, rgba(255,255,255,.46), rgba(255,255,255,.06) 42%, rgba(255,255,255,0) 60%);
  --card-alpha: 66%;
}
html.dark {
  --glass-bg: rgba(40, 38, 33, .46);
  --glass-bg-strong: rgba(40, 38, 33, .60);
  --glass-border: rgba(255, 255, 255, .14);
  --glass-inset: inset 0 1px 0 rgba(255, 255, 255, .16), inset 0 0 0 .5px rgba(255, 255, 255, .07);
  --glass-shadow: 0 8px 28px rgba(0, 0, 0, .38);
  --glass-sheen: linear-gradient(120deg, rgba(255,255,255,.14), rgba(255,255,255,.02) 42%, rgba(255,255,255,0) 60%);
  --card-alpha: 42%;
}

/* 环境光斑：清透蓝白基调（Solyra 风） */
body::before {
  content: "";
  position: fixed; inset: -12%;
  z-index: -1; pointer-events: none;
  background:
    radial-gradient(38% 30% at 18% 8%, rgba(140, 176, 255, .40), transparent 62%),
    radial-gradient(30% 24% at 88% 12%, rgba(186, 214, 255, .42), transparent 60%),
    radial-gradient(40% 32% at 76% 74%, rgba(160, 214, 245, .34), transparent 62%),
    radial-gradient(34% 26% at 14% 86%, rgba(200, 224, 252, .40), transparent 60%);
  filter: blur(30px);
}
html.dark body::before { opacity: .5; }

/* 玻璃基类：所有主要表面统一质感 */
.icon-btn, .sch-pill, .today-pill, .week-picker, .sheet, .pop-card,
.toast, .sem-row, details.sec, .drop-box, .ocr-card,
.sch-item.current, .t-row, .ocr-row, .sheet-grip {
  background-color: var(--glass-bg);
  background-image: var(--glass-sheen);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-sat));
  backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-sat));
  border: 1px solid var(--glass-border);
  box-shadow: var(--glass-inset), var(--glass-shadow);
}
.sheet, .week-picker, .pop-card, .ocr-card, .drop-box {
  background-color: var(--glass-bg-strong);
  -webkit-backdrop-filter: blur(40px) saturate(var(--glass-sat));
  backdrop-filter: blur(40px) saturate(var(--glass-sat));
}
.icon-btn:active, .sch-pill:active, .today-pill:active { filter: brightness(1.06); transform: scale(.94); }

/* 课程卡片：半透明玻璃马卡龙（回退=原实色） */
.course {
  background: color-mix(in srgb, var(--card) 80%, transparent);
  -webkit-backdrop-filter: blur(16px) saturate(150%);
  backdrop-filter: blur(16px) saturate(150%);
  border: .5px solid rgba(255, 255, 255, .55);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .45), 0 3px 12px rgba(45, 70, 120, .10);
  transition: transform .14s ease, box-shadow .14s ease;
}
.course:active { transform: scale(.975); box-shadow: inset 0 1px 0 rgba(255,255,255,.45), 0 2px 6px rgba(45,70,120,.12); }
html.dark .course { background: color-mix(in srgb, var(--card) 88%, transparent); border-color: rgba(255, 255, 255, .10); box-shadow: inset 0 1px 0 rgba(255, 255, 255, .08), 0 3px 12px rgba(0,0,0,.28); }

/* 输入类表面：轻玻璃 */
.f-input, .pedit-t, .sem-row input, select.f-input {
  background: var(--glass-bg);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  border-color: rgba(255, 255, 255, .5);
}
.chip { background: var(--glass-bg); border-color: var(--glass-border); }
.chip.on { background: color-mix(in srgb, var(--blue) 16%, transparent); }
html.dark .f-input, html.dark .pedit-t { border-color: rgba(255,255,255,.14); }
html.dark .chip { background: rgba(255,255,255,.06); border-color: rgba(255,255,255,.14); }

/* 深色模式玻璃微调 */
html.dark .icon-btn, html.dark .sch-pill, html.dark .sch-item.current,
html.dark .sem-row, html.dark .ocr-row, html.dark .t-row, html.dark details.sec {
  background-color: var(--glass-bg);
  background-image: var(--glass-sheen);
}

/* K70 / 20:9 长屏与 430-460px 视口适配 */
@media (min-width: 420px) and (max-width: 470px) {
  :root { --row-h: 66px; }
  .date-title { font-size: 23px; }
  .course .cname { font-size: 12px; }
  .course .cloc { font-size: 10.5px; }
  .icon-btn { width: 34px; height: 34px; }
}
@media (min-height: 920px) {
  :root { --row-h: 68px; }
}
@media (min-width: 560px) {
  #app { max-width: 430px; margin: 0 auto; box-shadow: 0 0 60px rgba(45,70,120,.09); }
  .week-picker { left: calc(50% - 199px); }
}
@media (max-height: 700px) { :root { --row-h: 54px; } }

/* ═══ 深色模式：变量与文字（液态玻璃版） ═══ */
html.dark {
  --bg: #141922;
  --card: #202733;
  --ink: #E4E9F1;
  --ink-2: #99A3B2;
  --ink-3: #626C7A;
  --blue-soft: rgba(90, 130, 235, .22);
  --line: #33312B;
  --c0-bg: #3A4528; --c1-bg: #4F3D26; --c2-bg: #3B3556; --c3-bg: #4E2F35;
  --c4-bg: #4C3F1F; --c5-bg: #2A4257; --c6-bg: #28473A; --c7-bg: #323850;
  --c0-ink: #C9D8A8; --c1-ink: #E8C79A; --c2-ink: #C4B8F0; --c3-ink: #F0B5C0;
  --c4-ink: #EBD694; --c5-ink: #A6CFEE; --c6-ink: #A4DCC4; --c7-ink: #BCC4E8;
}
html.dark .date-title { color: #EEF2F8; }
html.dark .wb-month { color: #AAB4C2; }
html.dark .wb-day .wd, html.dark .wb-day .dn { color: #AAB4C2; }
html.dark .wb-day:not(.today):active .dn { background: #262E3A; }
html.dark .time-cell .tn { color: #D8DEE7; }
html.dark .course .cname { color: var(--ink); }
html.dark .sheet h2, html.dark .pop-card .p-name { color: #EEF2F8; }
html.dark .sch-name, html.dark .t-name, html.dark .p-v, html.dark .t-time,
html.dark details.sec summary, html.dark .sem-row label, html.dark .pedit-n { color: var(--ink); }
html.dark .sch-item:active { background: rgba(255,255,255,.05); }
html.dark .ghost-btn { border-color: rgba(255,255,255,.16); color: var(--ink-2); }
html.dark .pop-close { background: rgba(255,255,255,.10); color: var(--ink); }
html.dark .sheet-grip { background: #39414E; }
html.dark .toast { background: rgba(235,232,225,.90); color: #26241F; -webkit-backdrop-filter: none; backdrop-filter: none; }
html.dark .t-badge.done { background: rgba(255,255,255,.10); color: var(--ink-2); }

/* ═══ 玻璃效果降级（弱 GPU / 用户关闭） ═══ */
html.no-glass body::before { filter: none; opacity: .42; }
html.no-glass .icon-btn, html.no-glass .sch-pill, html.no-glass .today-pill,
html.no-glass .week-picker, html.no-glass .sheet, html.no-glass .pop-card,
html.no-glass .toast, html.no-glass .sem-row, html.no-glass details.sec,
html.no-glass .drop-box, html.no-glass .ocr-card, html.no-glass .sch-item.current,
html.no-glass .t-row, html.no-glass .ocr-row {
  -webkit-backdrop-filter: none; backdrop-filter: none;
  background-color: rgba(255, 255, 255, .82);
  background-image: var(--glass-sheen);
}
html.no-glass .sheet, html.no-glass .week-picker, html.no-glass .pop-card,
html.no-glass .ocr-card, html.no-glass .drop-box { background-color: rgba(253, 252, 248, .94); }
html.no-glass .course {
  background: var(--cc, var(--c0-bg));
  -webkit-backdrop-filter: none; backdrop-filter: none;
}
html.no-glass .f-input, html.no-glass .pedit-t { -webkit-backdrop-filter: none; backdrop-filter: none; }
html.dark.no-glass .icon-btn, html.dark.no-glass .sch-pill, html.dark.no-glass .today-pill,
html.dark.no-glass .week-picker, html.dark.no-glass .sheet, html.dark.no-glass .pop-card,
html.dark.no-glass .toast, html.dark.no-glass .sem-row, html.dark.no-glass details.sec,
html.dark.no-glass .drop-box, html.dark.no-glass .ocr-card, html.dark.no-glass .sch-item.current,
html.dark.no-glass .t-row, html.dark.no-glass .ocr-row {
  background-color: rgba(30, 37, 48, .94);
}
html.dark.no-glass .sheet, html.dark.no-glass .week-picker, html.dark.no-glass .pop-card,
html.dark.no-glass .ocr-card, html.dark.no-glass .drop-box { background-color: #1E2530; }
html.dark.no-glass .course { background: var(--cc, var(--c0-bg)); }

/* ═══════════════════════════════════════════
   v1.2 新增：回本周胶囊 / 倒计时 / 课程统计
   ═══════════════════════════════════════════ */
.now-week-pill {
  align-self: flex-start;
  display: inline-flex; align-items: center;
  margin: 6px 0 0 16px; padding: 5px 12px;
  background: #E7EDF6; border-radius: 20px;
  font-size: 11.5px; font-weight: 600; color: #5D6672;
  max-width: calc(100% - 32px);
}
.now-week-pill:active { filter: brightness(.96); }
html.dark .now-week-pill { background: rgba(255,255,255,.08); color: var(--ink-2); }

.cd-pill {
  align-self: flex-start;
  display: inline-flex; align-items: center;
  margin: 6px 0 0 16px; padding: 5px 12px;
  background: #FBEED9; border-radius: 20px;
  font-size: 11.5px; font-weight: 600; color: #B4763A;
  max-width: calc(100% - 32px);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.cd-pill:active { filter: brightness(.96); }
html.dark .cd-pill { background: rgba(232,169,111,.16); color: #E8C79A; }

/* 周选择器「回到本周」 */
.wp-back { color: var(--blue); font-weight: 600; justify-content: center; margin-bottom: 2px; }

/* 粘贴文本导入 */
.ti-area { width: 100%; resize: vertical; line-height: 1.65; font-size: 13.5px; }

/* 倒计时管理（设置面板） */
.cd-row { display: flex; align-items: center; gap: 8px; padding: 9px 2px; border-bottom: 1px solid var(--line); }
.cd-row:last-of-type { border-bottom: none; }
.cd-row.past { opacity: .5; }
.cd-main { flex: 1; min-width: 0; }
.cd-name { font-size: 13.5px; font-weight: 600; color: #33383F; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cd-date { font-size: 11px; color: var(--ink-2); margin-top: 1px; }
html.dark .cd-name { color: var(--ink); }
.cd-add { display: flex; gap: 8px; margin-top: 8px; }
.cd-add .f-input { padding: 8px 10px; font-size: 13px; }
.cd-add #cdName { flex: 1.4; }
.cd-add #cdDate { flex: 1; min-width: 0; }

/* 今日面板倒计时 chips */
.cd-chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 2px 0 10px; }
.cd-chip {
  font-size: 11px; font-weight: 600; color: #B4763A;
  background: #FBEED9; padding: 4px 9px; border-radius: 12px;
}
html.dark .cd-chip { background: rgba(232,169,111,.16); color: #E8C79A; }

/* 课程统计 */
.stat-cards { display: flex; gap: 9px; margin-top: 4px; }
.stat-card {
  flex: 1; text-align: center; padding: 12px 8px;
  background: var(--glass-bg); background-image: var(--glass-sheen);
  border: 1px solid var(--glass-border); border-radius: 13px;
  box-shadow: var(--glass-inset);
}
.stat-card b { display: block; font-size: 20px; font-weight: 700; color: var(--blue); }
.stat-card small { font-size: 10.5px; color: var(--ink-2); }
.stat-bars { display: flex; align-items: stretch; gap: 7px; margin-top: 8px; height: 88px; }
.stat-bar-col {
  flex: 1; display: flex; flex-direction: column; align-items: center;
  justify-content: flex-end; gap: 4px; min-width: 0;
}
.stat-bar {
  width: 100%; max-width: 30px;
  background: color-mix(in srgb, var(--blue) 18%, transparent);
  border: 1px solid color-mix(in srgb, var(--blue) 34%, transparent);
  border-radius: 7px 7px 3px 3px;
  display: flex; align-items: flex-start; justify-content: center;
}
.stat-bar small { font-size: 10px; font-weight: 700; color: var(--blue); padding-top: 3px; }
.stat-bar-col > small { font-size: 10px; color: var(--ink-2); }
.stat-list { display: flex; flex-direction: column; gap: 7px; margin-top: 8px; }
.stat-row {
  display: flex; justify-content: space-between; align-items: center; gap: 10px;
  font-size: 12.5px; padding: 8px 11px;
  background: var(--glass-bg); border: 1px solid var(--glass-border); border-radius: 11px;
}
.stat-name { font-weight: 600; color: #33383F; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.stat-val { color: var(--ink-2); flex: none; }
html.dark .stat-name { color: var(--ink); }
html.no-glass .stat-card, html.no-glass .stat-row { background-color: rgba(255,255,255,.82); }
html.dark.no-glass .stat-card, html.dark.no-glass .stat-row { background-color: rgba(43,41,37,.90); }

/* ═══════════════════════════════════════════
   v1.4 UI 重构（Solyra 参考）：视图框架 / Today / 时间线 / 底部Tab / 材质
   ═══════════════════════════════════════════ */

/* ── 视图框架 ── */
#app { padding-bottom: calc(var(--sab) + 62px); }
.view { height: 100%; display: flex; flex-direction: column; }
.vw-page { flex: 1; display: flex; flex-direction: column; min-height: 0; }

/* ── 分段控件 ── */
.seg-wrap { padding: calc(var(--sat) + 10px) 16px 0; }
.seg {
  display: flex; gap: 2px; padding: 3px;
  background: var(--glass-bg-strong);
  background-image: var(--glass-sheen);
  border: 1px solid var(--glass-border);
  border-radius: 14px;
  box-shadow: var(--glass-inset), 0 2px 10px rgba(45,70,120,.10);
}
.seg button {
  flex: 1; padding: 7px 0; border-radius: 11px;
  font-size: 13px; font-weight: 600; color: var(--ink-2);
  transition: background .15s ease, color .15s ease;
}
.seg button.on { background: var(--card); color: var(--blue); box-shadow: 0 1px 5px rgba(45,70,120,.14); }
.seg.mini { box-shadow: none; border-radius: 11px; }
.seg.mini button { padding: 5px 0; font-size: 11.5px; }
/* ── 大标题头（Today / 时间线 / 统计 / 我的） ── */
.today-head { padding: 12px 20px 4px; }
.t-date { font-size: 12.5px; font-weight: 600; color: var(--ink-2); }
.t-title { font-size: 24px; font-weight: 800; letter-spacing: .2px; color: #22272F; margin-top: 2px; }
html.dark .t-title { color: #EEF2F8; }

/* ── Today：下一节课高亮卡 ── */
.next-card {
  margin: 10px 16px 0; padding: 13px 15px;
  border-radius: 16px;
  background: color-mix(in srgb, var(--c3-bg) 40%, transparent);
  border: 1px solid color-mix(in srgb, var(--c3-bar) 38%, transparent);
  box-shadow: 0 4px 16px rgba(45,70,120,.10);
  display: flex; align-items: center; gap: 12px;
  text-align: left; width: calc(100% - 32px);
}
.next-card:active { filter: brightness(.98); }
.next-card .nc-label { display: flex; align-items: center; gap: 5px; font-size: 11px; font-weight: 700; color: #C05E6E; margin-bottom: 4px; }
.next-card .nc-name { font-size: 16px; font-weight: 700; color: var(--ink); line-height: 1.3; }
.next-card .nc-meta { display: flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); margin-top: 4px; }
.next-card .nc-arrow { margin-left: auto; color: var(--ink-3); flex: none; font-size: 16px; }
html.dark .next-card .nc-label { color: #F0B5C0; }

/* ── Today / 时间线：课程行 ── */
.rest-sec { margin: 16px 16px 0; }
.rest-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.rest-title { font-size: 15px; font-weight: 700; color: var(--ink); }
.rest-sub { font-size: 11.5px; color: var(--ink-2); font-weight: 600; }
.rest-list { display: flex; flex-direction: column; gap: 8px; }
.rest-row {
  display: flex; align-items: center; gap: 11px;
  background: var(--card); border-radius: 14px; padding: 11px 13px;
  box-shadow: 0 1px 6px rgba(45,70,120,.07);
  text-align: left; width: 100%;
}
.rest-row:active { background: #F2F6FD; }
html.dark .rest-row { background: var(--card); }
html.dark .rest-row:active { background: #262E3B; }
.rest-row.done { opacity: .5; }
.rest-row.now { box-shadow: inset 0 0 0 1.5px var(--blue), 0 2px 10px rgba(61,123,247,.14); }
.rr-time { flex: none; width: 46px; text-align: center; }
.rr-time b { display: block; font-size: 14px; font-weight: 700; color: var(--ink); line-height: 1.2; }
.rr-time small { font-size: 10px; color: var(--ink-3); }
.rr-bar { flex: none; width: 4px; height: 34px; border-radius: 2px; background: var(--rc, var(--blue)); }
.rr-main { flex: 1; min-width: 0; }
.rr-name { display: block; font-size: 14px; font-weight: 650; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rr-meta { display: block; font-size: 11px; color: var(--ink-2); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rr-badge { flex: none; font-size: 10px; font-weight: 700; padding: 4px 8px; border-radius: 8px; background: var(--blue-soft); color: var(--blue); }
.rr-badge.done { background: #E7EDF6; color: var(--ink-2); }
.rr-empty { text-align: center; padding: 30px 0 10px; color: var(--ink-2); font-size: 13.5px; }
.tl-dayhead { display: flex; align-items: baseline; gap: 7px; margin: 18px 4px 8px; }
.tl-dayhead b { font-size: 14px; font-weight: 700; color: var(--ink); }
.tl-dayhead small { font-size: 11px; color: var(--ink-3); }
.tl-dayhead.today b { color: var(--blue); }

/* ── 底部 Tab 栏 ── */
.tabbar {
  position: fixed; z-index: 45;
  left: 50%; transform: translateX(-50%);
  bottom: calc(var(--sab) + 8px);
  width: min(430px, calc(100% - 24px));
  display: flex; padding: 6px 10px;
  background: var(--glass-bg-strong);
  background-image: var(--glass-sheen);
  -webkit-backdrop-filter: blur(30px) saturate(var(--glass-sat));
  backdrop-filter: blur(30px) saturate(var(--glass-sat));
  border: 1px solid var(--glass-border);
  border-radius: 22px;
  box-shadow: var(--glass-inset), 0 8px 28px rgba(35,55,95,.16);
}
.tabbar button {
  flex: 1; display: flex; flex-direction: column; align-items: center; gap: 2px;
  padding: 5px 0 4px; color: var(--ink-3); border-radius: 14px;
  font-size: 10.5px; font-weight: 600;
}
.tabbar button.on { color: var(--blue); background: var(--blue-soft); }
html.no-glass .tabbar { background: rgba(252, 253, 255, .96); }
html.dark.no-glass .tabbar { background: rgba(30, 37, 48, .96); }

/* ── 统计/我的 常驻页 ── */
.page-body { padding: 6px 16px calc(var(--sab) + 20px); overflow-y: auto; flex: 1; min-height: 0; }
.me-row-btns { display: flex; gap: 10px; margin-top: 8px; }
.me-row-btns > * { flex: 1; }

/* ── 材质四档（跟随系统/清透/磨砂/经典） ── */
html.m-frost { --glass-blur: 34px; --glass-bg: rgba(255,255,255,.72); --glass-bg-strong: rgba(255,255,255,.84); }
html.dark.m-frost { --glass-bg: rgba(38,46,58,.78); --glass-bg-strong: rgba(38,46,58,.88); }
html.m-classic { --glass-bg: rgba(255,255,255,.96); --glass-bg-strong: rgba(255,255,255,.99); }
html.dark.m-classic { --glass-bg: rgba(30,37,48,.98); --glass-bg-strong: rgba(30,37,48,.99); }
html.m-classic .icon-btn, html.m-classic .sch-pill, html.m-classic .week-picker, html.m-classic .sheet,
html.m-classic .pop-card, html.m-classic .toast, html.m-classic .sem-row, html.m-classic details.sec,
html.m-classic .drop-box, html.m-classic .ocr-card, html.m-classic .sch-item.current,
html.m-classic .t-row, html.m-classic .ocr-row, html.m-classic .today-pill {
  -webkit-backdrop-filter: none !important; backdrop-filter: none !important;
}

/* ═══════════════════════════════════════════
   v1.6：液态玻璃滑动指示器 + 视图切换动画 + 图标玻璃质感
   ═══════════════════════════════════════════ */

/* ── 分段控件：滑动玻璃滑块 ── */
.seg { position: relative; overflow: hidden; }
.seg .seg-thumb {
  position: absolute; top: 3px; bottom: 3px; left: 0; width: 40px;
  border-radius: 11px; z-index: 0;
  background: var(--card);
