/* util.js — 日期/节次/通用工具 */
'use strict';

/** 默认节次时间表（15 节，每节 45 分钟 + 课间 10 分钟，可按学校作息在设置里改） */
const PERIODS = [
  { n: 1,  start: '08:00', end: '08:45' },
  { n: 2,  start: '08:55', end: '09:40' },
  { n: 3,  start: '10:00', end: '10:45' },
  { n: 4,  start: '10:55', end: '11:40' },
  { n: 5,  start: '11:50', end: '12:35' },
  { n: 6,  start: '13:10', end: '13:55' },
  { n: 7,  start: '14:00', end: '14:45' },
  { n: 8,  start: '14:55', end: '15:40' },
  { n: 9,  start: '16:00', end: '16:45' },
  { n: 10, start: '16:55', end: '17:40' },
  { n: 11, start: '17:50', end: '18:35' },
  { n: 12, start: '19:00', end: '19:45' },
  { n: 13, start: '19:55', end: '20:40' },
  { n: 14, start: '20:50', end: '21:35' },
  { n: 15, start: '21:45', end: '22:30' },
];

/** 马卡龙配色数（与 style.css 的 --c0..--c7 对应） */
const PALETTE_SIZE = 8;

const WEEKDAY_NAMES = ['周一', '周二', '周三', '周四', '周五', '周六', '周日'];

function pad2(n) { return n < 10 ? '0' + n : '' + n; }

/** 周一 00:00（本地时区） */
function mondayOf(date) {
  const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const wd = (d.getDay() + 6) % 7; // 周一=0
  d.setDate(d.getDate() - wd);
  return d;
}

function addDays(date, n) {
  const d = new Date(date.getTime());
  d.setDate(d.getDate() + n);
  return d;
}

function sameDay(a, b) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

/** '2026-08-31' → 本地 Date（当日 00:00） */
function parseISO(iso) {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, m - 1, d);
}

function toISO(date) {
  return date.getFullYear() + '-' + pad2(date.getMonth() + 1) + '-' + pad2(date.getDate());
}

/** 开学日（必须是某周周一）→ 第几周（1 起） */
function weekIndexOf(semesterStart, date) {
  const ms = Math.floor(mondayOf(date).getTime() / 86400000) - Math.floor(mondayOf(semesterStart).getTime() / 86400000);
  return Math.floor(ms / 7) + 1;
}

/** 日期 → '2026年9月1日' */
function formatCN(date) {
  return date.getFullYear() + '年' + (date.getMonth() + 1) + '月' + date.getDate() + '日';
}

/** 'HH:MM' → 当日分钟数 */
function minutesOf(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

/** 时间字符串（'HH:MM' 或 'HHMMSS'）规整为 'HH:MM' */
function normTime(t) {
  const m = /^(\d{1,2}):?(\d{2})/.exec(t.trim());
  return m ? pad2(+m[1]) + ':' + m[2] : null;
}

/** 事件起止时间 → 吸附到的 [startPeriod, endPeriod]（periods 缺省用默认时间表）；无法识别返回 null */
function snapToPeriods(startHHMM, endHHMM, periods) {
  periods = periods || PERIODS;
  const s = normTime(startHHMM), e = normTime(endHHMM);
  if (!s || !e) return null;
  const sm = minutesOf(s), em = minutesOf(e);
  let bestP = null, bestE = null;
  for (const p of periods) {
    const ps = minutesOf(p.start), pe = minutesOf(p.end);
    if (bestP === null || Math.abs(ps - sm) < Math.abs(minutesOf(periods[bestP - 1].start) - sm)) bestP = p.n;
    if (bestE === null || Math.abs(pe - em) < Math.abs(minutesOf(periods[bestE - 1].end) - em)) bestE = p.n;
  }
  if (bestP === null) return null;
  if (bestE < bestP) bestE = bestP;
  return [bestP, bestE];
}

/** 周次数组 → 紧凑文本，如 [1,2,3,5,7,8] → '1-3,5,7-8 周' */
function toRangeText(weeks) {
  const s = weeks.slice().sort((a, b) => a - b);
  const parts = [];
  let start = s[0], prev = s[0];
  for (let i = 1; i <= s.length; i++) {
    if (s[i] === prev + 1) { prev = s[i]; continue; }
    parts.push(start === prev ? String(start) : start + '-' + prev);
    start = prev = s[i];
  }
  return parts.join(',') + ' 周';
}

function uid() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/** 数组去重（JSON 序列化比较） */
function uniqBy(arr, keyFn) {
  const seen = new Set(), out = [];
  for (const it of arr) {
    const k = keyFn(it);
    if (!seen.has(k)) { seen.add(k); out.push(it); }
  }
  return out;
}

