/* edit.js — 手动添加 / 编辑课程（底部表单） */
'use strict';

const CourseEditor = {
  /** 打开表单。courseId 传空 = 新增（可带 day 默认值） */
  open(courseId, defaults) {
    const sch = Store.active();
    if (!sch) {
      // 没有课表时自动创建一个
      const s = Store.addSchedule('我的课表', []);
      Store.setActive(s.id);
      App.initState();
      App.refresh();
      return this.open(courseId, defaults);
    }
    const old = document.getElementById('editSheet');
    if (old) old.remove();

    const c = courseId ? sch.courses.find(x => x.id === courseId) : null;
    const v = c || Object.assign({ name: '', loc: '', teacher: '', day: 1, p1: 1, p2: 2, weeks: [], color: null }, defaults || {});

    const dayChips = [1, 2, 3, 4, 5, 6, 7].map(d =>
      '<button type="button" class="chip' + (v.day === d ? ' on' : '') + '" data-day="' + d + '">周' + '一二三四五六日'[d - 1] + '</button>').join('');
    const periods = Store.periodsOf(sch);
    const periodOpts = (sel) => periods.map(p => '<option value="' + p.n + '"' + (p.n === sel ? ' selected' : '') + '>第' + p.n + '节 ' + p.start + '</option>').join('');
    const weeksMode = !c || !v.weeks || !v.weeks.length ? 'all' : this.detectMode(v.weeks);
    const modeChips = [['all', '每周'], ['odd', '单周'], ['even', '双周'], ['custom', '自定义']].map(([k, t]) =>
      '<button type="button" class="chip' + (weeksMode === k ? ' on' : '') + '" data-mode="' + k + '">' + t + '</button>').join('');

    const el = document.createElement('div');
    el.id = 'editSheet';
    el.innerHTML = '<div class="sheet-mask show" id="editMask"></div>' +
      '<div class="sheet show" role="dialog">' +
      '<div class="sheet-grip"></div>' +
      '<h2>' + (c ? '编辑课程' : '添加课程') + '</h2>' +
      '<div class="form">' +
      '<label class="f-label">课程名称</label>' +
      '<input id="fName" class="f-input" type="text" placeholder="如：高等数学 A(1)" value="' + esc(v.name) + '">' +
      '<label class="f-label">地点（可选）</label>' +
      '<input id="fLoc" class="f-input" type="text" placeholder="如：理教 A101" value="' + esc(v.loc || '') + '">' +
      '<label class="f-label">老师（可选）</label>' +
      '<input id="fTeacher" class="f-input" type="text" placeholder="如：王老师" value="' + esc(v.teacher || '') + '">' +
      '<label class="f-label">星期</label><div class="chips" id="fDays">' + dayChips + '</div>' +
      '<label class="f-label">节次</label>' +
      '<div class="f-row2">' +
      '<select id="fP1" class="f-input">' + periodOpts(v.p1) + '</select>' +
      '<span class="f-sep">至</span>' +
      '<select id="fP2" class="f-input">' + periodOpts(v.p2) + '</select>' +
      '</div>' +
      '<label class="f-label">周次</label><div class="chips" id="fModes">' + modeChips + '</div>' +
      '<input id="fWeeks" class="f-input" type="text" placeholder="如：1-8,10,12-16" style="display:' + (weeksMode === 'custom' ? 'block' : 'none') + '" value="' + (weeksMode === 'custom' ? toRangeText(v.weeks || []).replace(/ 周$/, '') : '') + '">' +
      '<label class="f-label">颜色</label><div class="chips" id="fColors">' +
      Array.from({ length: PALETTE_SIZE }, (_, i) =>
        '<button type="button" class="dot' + ((c ? c.color : i) === i ? ' on' : '') + '" data-color="' + i + '" style="background:var(--c' + i + '-bg);border-color:var(--c' + i + '-bar)"></button>').join('') +
      '</div>' +
      '<div class="f-btns">' +
      (c ? '<button class="danger-btn slim" id="fDel" type="button">删除课程</button>' : '') +
      '<button class="primary-btn wide" id="fSave" type="button">保存</button>' +
      '<button class="ghost-btn wide" id="fCancel" type="button">取消</button>' +
      '</div></div></div>';
    document.body.appendChild(el);
    const rec = App.trackOverlay(() => el.remove());

    // 状态
    const st = { day: v.day, mode: weeksMode, color: c ? c.color : Store.colorFor(v.name || '课程') };

    el.querySelector('#fDays').addEventListener('click', (e) => {
      const b = e.target.closest('[data-day]'); if (!b) return;
      st.day = +b.dataset.day;
      el.querySelectorAll('#fDays .chip').forEach(x => x.classList.toggle('on', x === b));
    });
    el.querySelector('#fModes').addEventListener('click', (e) => {
      const b = e.target.closest('[data-mode]'); if (!b) return;
      st.mode = b.dataset.mode;
      el.querySelectorAll('#fModes .chip').forEach(x => x.classList.toggle('on', x === b));
      el.querySelector('#fWeeks').style.display = st.mode === 'custom' ? 'block' : 'none';
    });
    el.querySelector('#fColors').addEventListener('click', (e) => {
      const b = e.target.closest('[data-color]'); if (!b) return;
      st.color = +b.dataset.color;
      el.querySelectorAll('#fColors .dot').forEach(x => x.classList.toggle('on', x === b));
    });
    el.querySelector('#fCancel').addEventListener('click', () => rec.close());
    el.querySelector('#editMask').addEventListener('click', () => rec.close());
    if (c) el.querySelector('#fDel').addEventListener('click', () => {
      Store.removeCourse(sch.id, c.id);
      rec.close();
      App.refresh();
      toast('已删除课程', 'ok');
    });
    el.querySelector('#fSave').addEventListener('click', () => {
      const name = el.querySelector('#fName').value.trim();
      if (!name) { toast('请填写课程名称', 'err'); return; }
      const p1 = +el.querySelector('#fP1').value, p2 = +el.querySelector('#fP2').value;
      let weeks = [];
      if (st.mode === 'odd') weeks = odds(Store.totalWeeks());
      else if (st.mode === 'even') weeks = evens(Store.totalWeeks());
      else if (st.mode === 'custom') {
        weeks = parseWeeksText(el.querySelector('#fWeeks').value);
        if (!weeks) { toast('周次格式不对，例：1-8,10,12-16', 'err'); return; }
      }
      const loc = el.querySelector('#fLoc').value.trim().replace(/^@+/, '');
      const teacher = el.querySelector('#fTeacher').value.trim();
      const p2max = Math.max(p1, p2);
      // 时间冲突检测（排除自身）
      const clash = sch.courses.find(x => x.id !== (c ? c.id : null) && x.day === st.day && x.p1 <= p2max && x.p2 >= p1);
      if (clash && !confirm('与「' + clash.name + '」时间冲突（周' + '一二三四五六日'[st.day - 1] + ' 第' + clash.p1 + '-' + clash.p2 + '节），仍要保存？')) return;
      const data = { name, loc, teacher, day: st.day, p1, p2: p2max, weeks, color: st.color };
      if (c) {
        Store.updateCourse(sch.id, c.id, data);
        toast('已保存', 'ok');
      } else {
        Store.addCourse(sch.id, data);
        toast('已添加「' + name + '」', 'ok');
      }
      rec.close();
      App.refresh();
    });

    el.querySelector('#fName').focus();
  },

  /** 已有周次数组 → 表单模式 */
  detectMode(weeks) {
    const s = weeks.slice().sort((a, b) => a - b);
    const odd = s.every(w => w % 2 === 1), even = s.every(w => w % 2 === 0);
    if (odd) return 'odd';
    if (even) return 'even';
    return 'custom';
  },
};

/** '1-8,10,12-16' → 数组；非法返回 null；空串 = []（每周） */
function parseWeeksText(t) {
  t = (t || '').trim().replace(/周/g, '');
  if (!t) return [];
  if (!/^[\d,\-\s]+$/.test(t)) return null;
  const out = [];
  for (const seg of t.split(/[,，]/)) {
    const s = seg.trim();
    if (!s) continue;
    const m = /^(\d+)-(\d+)$/.exec(s);
    if (m) {
      const a = +m[1], b = +m[2];
      if (a < 1 || b < a || b > 60) return null;
      for (let i = a; i <= b; i++) out.push(i);
    } else if (/^\d+$/.test(s)) {
      out.push(+s);
    } else return null;
  }
  return [...new Set(out)].sort((a, b) => a - b);
}

function odds(max) { const a = []; for (let i = 1; i <= max; i += 2) a.push(i); return a; }
function evens(max) { const a = []; for (let i = 2; i <= max; i += 2) a.push(i); return a; }

