/* import.js — ICS 一键导入：文件选择 + 拖拽 + 导入管线 */
'use strict';

const Importer = {
  init() {
    const input = document.getElementById('icsFileInput');
    input.addEventListener('change', () => {
      this.handleFiles([...input.files]);
      input.value = '';
    });

    // 点击导入按钮
    document.getElementById('btnAdd').addEventListener('click', () => this.pick());

    // 拖拽导入
    const overlay = document.getElementById('dropOverlay');
    let dragDepth = 0;
    document.addEventListener('dragenter', (e) => {
      e.preventDefault();
      dragDepth++;
      overlay.hidden = false;
    });
    document.addEventListener('dragover', (e) => e.preventDefault());
    document.addEventListener('dragleave', () => {
      dragDepth = Math.max(0, dragDepth - 1);
      if (dragDepth === 0) overlay.hidden = true;
    });
    document.addEventListener('drop', (e) => {
      e.preventDefault();
      dragDepth = 0;
      overlay.hidden = true;
      if (e.dataTransfer && e.dataTransfer.files.length) {
        this.handleFiles([...e.dataTransfer.files]);
      }
    });
  },

  pick() { document.getElementById('icsFileInput').click(); },

  /** 处理一组 .ics 文件（一键导入多文件 = 多课表） */
  async handleFiles(files) {
    const icsFiles = files.filter(f => /\.ics$/i.test(f.name) || /calendar/i.test(f.type));
    if (!icsFiles.length) {
      toast('请选择 .ics 日历文件', 'err');
      return;
    }
    let lastSch = null, totalCourses = 0, skipped = 0;
    for (const f of icsFiles) {
      try {
        const text = await f.text();
        const r = this.importText(text, f.name.replace(/\.ics$/i, ''));
        if (r.ok) { lastSch = r.sch; totalCourses += r.n; skipped += r.skipped; }
        else toast('「' + f.name + '」里没有可导入的课程事件', 'err');
      } catch (err) {
        console.error(err);
        toast('「' + f.name + '」解析失败', 'err');
      }
    }
    if (lastSch) {
      Store.setActive(lastSch.id);
      App.initStateKeepWeek();
      App.refresh();
      toast('已导入「' + lastSch.name + '」：' + totalCourses + ' 门课' + (skipped ? '（' + skipped + ' 个全天事件已跳过）' : ''), 'ok');
    }
  },

  /** ICS 文本 → 新课表；返回 {ok, sch, n, skipped} */
  importText(text, name) {
    const parsed = ICS.parse(text);
    const nOcc = parsed.events.reduce((s, e) => s + e.occurrences.length, 0);
    if (!nOcc) return { ok: false, sch: null, n: 0, skipped: 0 };
    const { courses, semesterStart } = ICS.toCourses(parsed);
    if (!courses.length) return { ok: false, sch: null, n: 0, skipped: parsed.skipped.allDay };
    const schName = parsed.calName || name;
    const sch = Store.addSchedule(schName, courses, semesterStart);
    return { ok: true, sch, n: courses.length, skipped: parsed.skipped.allDay };
  },
};

/** toast 提示 */
let toastTimer = null;
function toast(msg, type) {
  const el = document.getElementById('toast');
  el.textContent = msg;
  el.className = 'toast show ' + (type || '');
  el.hidden = false;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { el.className = 'toast'; el.hidden = true; }, 3200);
}

