/* store.js — 数据模型与 localStorage 持久化
 * data = { schedules: [schedule], activeId }
 * schedule = { id, name, semesterStart:'YYYY-MM-DD'(周一), createdAt, courses:[course] }
 * course  = { id, name, loc, day:1-7, p1:1, p2:15, weeks:[int] (空数组=每周), color:0-7 }
 */
'use strict';

const Store = {
  KEY: 'kb_data_v1',
  data: { schedules: [], activeId: null },

  load() {
    try {
      const raw = localStorage.getItem(this.KEY);
      if (raw) {
        const d = JSON.parse(raw);
        if (d && Array.isArray(d.schedules)) this.data = d;
      }
    } catch (e) { console.warn('store load failed', e); }
    return this.data;
  },

  save() {
    try { localStorage.setItem(this.KEY, JSON.stringify(this.data)); }
    catch (e) { console.warn('store save failed', e); }
  },

  active() {
    return this.data.schedules.find(s => s.id === this.data.activeId) || null;
  },

  /** 课表节次时间表（自定义或默认） */
  periodsOf(sch) {
    return (sch && Array.isArray(sch.periods) && sch.periods.length === PERIODS.length) ? sch.periods : PERIODS;
  },

  setPeriods(id, periods) {
    const s = this.data.schedules.find(x => x.id === id);
    if (s && Array.isArray(periods) && periods.length === PERIODS.length) {
      s.periods = periods.map((p, i) => ({ n: i + 1, start: p.start, end: p.end }));
      this.save();
      return true;
    }
    return false;
  },

  resetPeriods(id) {
    const s = this.data.schedules.find(x => x.id === id);
    if (s) { delete s.periods; this.save(); }
  },

  /** 外观偏好（跟随系统/浅色/深色 + 自定义背景色） */
  getPref(key, fallback) {
    try { return localStorage.getItem('kb_pref_' + key) || fallback; } catch (e) { return fallback; }
  },

  setPref(key, val) {
    try { localStorage.setItem('kb_pref_' + key, val); } catch (e) {}
  },

  /** 新建课表；semesterStart 缺省 = 本周周一 */
  addSchedule(name, courses, semesterStart) {
    const sch = {
      id: uid(),
      name: name || ('课表 ' + (this.data.schedules.length + 1)),
      semesterStart: semesterStart || toISO(mondayOf(new Date())),
      createdAt: Date.now(),
      colorIdx: this.data.schedules.length % PALETTE_SIZE,
      courses: courses || [],
    };
    this.data.schedules.push(sch);
    this.data.activeId = sch.id;
    this.save();
    return sch;
  },

  removeSchedule(id) {
    this.data.schedules = this.data.schedules.filter(s => s.id !== id);
    if (this.data.activeId === id) {
      this.data.activeId = this.data.schedules.length ? this.data.schedules[0].id : null;
    }
    this.save();
  },

  renameSchedule(id, name) {
    const s = this.data.schedules.find(x => x.id === id);
    if (s) { s.name = name; this.save(); }
  },

  setActive(id) { this.data.activeId = id; this.save(); },

  setSemesterStart(id, iso) {
    const s = this.data.schedules.find(x => x.id === id);
    if (s) { s.semesterStart = iso; this.save(); }
  },

  /** 手动添加/编辑课程 */
  addCourse(schId, course) {
    const s = this.data.schedules.find(x => x.id === schId);
    if (!s) return null;
    const c = Object.assign({ id: uid(), loc: '', weeks: [], color: this.colorFor(course.name || '课程') }, course);
    s.courses.push(c);
    this.save();
    return c;
  },

  updateCourse(schId, courseId, patch) {
    const s = this.data.schedules.find(x => x.id === schId);
    if (!s) return null;
    const c = s.courses.find(x => x.id === courseId);
    if (!c) return null;
    Object.assign(c, patch);
    this.save();
    return c;
  },

  removeCourse(schId, courseId) {
    const s = this.data.schedules.find(x => x.id === schId);
    if (!s) return false;
    const n = s.courses.length;
    s.courses = s.courses.filter(x => x.id !== courseId);
    if (s.courses.length !== n) { this.save(); return true; }
    return false;
  },

  /** 课程名 → 稳定配色索引 */
  colorFor(name) {
    let h = 0;
    for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
    return h % PALETTE_SIZE;
  },

  /** 当前课表总周数（供周选择器） */
  totalWeeks() {
    const sch = this.active();
    let maxW = 20;
    if (sch) {
      for (const c of sch.courses) {
        for (const w of (c.weeks || [])) if (w > maxW) maxW = w;
      }
    }
    return Math.max(20, Math.min(maxW + 2, 40));
  },
};

