/* extras.js — 倒计时（考试/事件）+ 课程统计面板
 * 倒计时存偏好（kb_pref_countdowns），首页胶囊 ≤14 天时显示，
 * 今日面板显示 ≤60 天 chips，桌面小组件顶部显示最近一条（≤14 天）。
 */
'use strict';

const Countdown = {
  list() {
    try {
      const a = JSON.parse(Store.getPref('countdowns', '') || '[]');
      return Array.isArray(a) ? a.filter(x => x && x.name && x.date) : [];
    } catch (e) { return []; }
  },
  save(a) { Store.setPref('countdowns', JSON.stringify(a)); },
  add(name, date) {
    const a = this.list();
    a.push({ id: uid(), name, date });
    this.save(a);
  },
  remove(id) { this.save(this.list().filter(x => x.id !== id)); },

  /** 距离日期的天数（今天=0，负数=已过）；日期非法返回 null */
  daysLeft(date) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date || '');
    if (!m) return null;
    const t = new Date(); t.setHours(0, 0, 0, 0);
    return Math.round((new Date(+m[1], +m[2] - 1, +m[3]) - t) / 86400000);
  },

  /** 最近的未过期倒计时；withinDays 限制最大剩余天数 */
  nearest(withinDays) {
    let best = null;
    for (const c of this.list()) {
      const dl = this.daysLeft(c.date);
      if (dl == null || dl < 0) continue;
      if (withinDays != null && dl > withinDays) continue;
      if (!best || dl < best.dl) best = { name: c.name, date: c.date, dl };
    }
    return best;
  },

  text(item) {
    if (!item) return '';
    return item.dl === 0 ? item.name + ' · 就是今天' : item.name + ' · 还有 ' + item.dl + ' 天';
  },
};

const Extras = {
  /* ── Today 页顶部倒计时 chips（≤14 天） ── */
  renderCdChips() {
    const el = document.getElementById('cdChipsHome');
    if (!el) return;
    const items = Countdown.list()
      .map(c => ({ c, dl: Countdown.daysLeft(c.date) }))
      .filter(x => x.dl != null && x.dl >= 0 && x.dl <= 14)
      .sort((a, b) => a.dl - b.dl)
      .slice(0, 2);
    el.innerHTML = items.map(x =>
      '<span class="cd-chip">🎯 ' + esc(x.c.name) + ' · ' + (x.dl === 0 ? '就是今天' : '还有 ' + x.dl + ' 天') + '</span>').join('');
  },

  /* ── 设置里「倒计时」区段 ── */
  cdSectionHtml() {
    const items = Countdown.list().slice().sort((a, b) => a.date.localeCompare(b.date));
    let html = '<div id="cdList">' + (items.length ? items.map(c => {
      const dl = Countdown.daysLeft(c.date);
      const tag = dl == null ? '' : dl < 0 ? '已过期' : dl === 0 ? '就是今天' : '还有 ' + dl + ' 天';
      return '<div class="cd-row' + (dl != null && dl < 0 ? ' past' : '') + '">' +
        '<div class="cd-main"><div class="cd-name">' + esc(c.name) + '</div>' +
        '<div class="cd-date">' + esc(c.date) + ' · ' + tag + '</div></div>' +
        '<button class="sch-act danger" data-cddel="' + c.id + '" title="删除">✕</button></div>';
    }).join('') : '<p class="sub" style="padding:2px 0 6px">还没有倒计时。可以添加「期末考试」等重要日期，首页和小组件会自动提醒。</p>') + '</div>' +
      '<div class="cd-add"><input id="cdName" class="f-input" type="text" placeholder="名称，如 期末考试">' +
      '<input id="cdDate" class="f-input" type="date"></div>' +
      '<button class="ghost-btn wide" id="cdAdd" style="margin-top:8px">＋ 添加倒计时</button>';
    return html;
  },

  bindCdSection(sheet) {
    const add = sheet.querySelector('#cdAdd');
    if (!add) return;
    const rerender = () => {
      const sec = sheet.querySelector('#cdSection .sec-body');
      if (sec) sec.innerHTML = this.cdSectionHtml();
      this.bindCdSection(sheet);
      this.renderCdChips();
    };
    add.addEventListener('click', () => {
      const name = sheet.querySelector('#cdName').value.trim();
      const date = sheet.querySelector('#cdDate').value;
      if (!name) { toast('请填写倒计时名称', 'err'); return; }
      if (!date) { toast('请选择日期', 'err'); return; }
      Countdown.add(name, date);
      toast('已添加「' + name + '」', 'ok');
      rerender();
    });
    for (const b of sheet.querySelectorAll('[data-cddel]')) {
      b.addEventListener('click', () => { Countdown.remove(b.dataset.cddel); rerender(); });
    }
  },

  /* ── 今日面板顶部倒计时 chips（≤60 天，最多 3 条） ── */
  todayChipsHtml() {
    const items = Countdown.list()
      .map(c => ({ c, dl: Countdown.daysLeft(c.date) }))
      .filter(x => x.dl != null && x.dl >= 0 && x.dl <= 60)
      .sort((a, b) => a.dl - b.dl)
      .slice(0, 3);
    if (!items.length) return '';
    return '<div class="cd-chips">' + items.map(x =>
      '<span class="cd-chip">🎯 ' + esc(x.c.name) + ' · ' + (x.dl === 0 ? '今天' : x.dl + ' 天后') + '</span>').join('') + '</div>';
  },

  /* ── 课程统计（「统计」Tab 常驻页） ── */
  renderStatsView() {
    const body = document.getElementById('statsBody');
    if (!body) return;
    const sch = Store.active();
    if (!sch) { body.innerHTML = '<div class="page-body"><p class="rr-empty">还没有课表，先去导入一个吧</p></div>'; return; }
    const old = document.getElementById('statsSheet');
    if (old) old.remove();

    const weekCourses = sch.courses.filter(c => !c.weeks || !c.weeks.length || c.weeks.includes(App.state.viewWeek));
    const perDay = [1, 2, 3, 4, 5, 6, 7].map(d => weekCourses.filter(c => c.day === d).length);
    const maxDay = Math.max(1, Math.max.apply(null, perDay));
    const sessions = weekCourses.reduce((s, c) => s + (c.p2 - c.p1 + 1), 0);
    const byName = {};
    for (const c of weekCourses) {
      const k = c.name;
      if (!byName[k]) byName[k] = { n: 0, secs: 0, loc: c.loc };
      byName[k].n++;
      byName[k].secs += (c.p2 - c.p1 + 1);
    }
    const names = Object.keys(byName).sort((a, b) => byName[b].n - byName[a].n || byName[b].secs - byName[a].secs);

    body.innerHTML = '<div class="page-body">' +
      '<p class="sub">' + esc(sch.name) + ' · 第 ' + App.state.viewWeek + ' 周</p>' +
      '<div class="stat-cards">' +
      '<div class="stat-card"><b>' + weekCourses.length + '</b><small>本周课程</small></div>' +
      '<div class="stat-card"><b>' + sessions + '</b><small>本周节数</small></div>' +
      '<div class="stat-card"><b>' + names.length + '</b><small>不同科目</small></div>' +
      '</div>' +
      '<div class="f-label" style="margin-top:14px">每天课量</div>' +
      '<div class="stat-bars">' + perDay.map((n, i) =>
        '<div class="stat-bar-col"><div class="stat-bar" style="height:' + Math.round(8 + 52 * n / maxDay) + 'px">' +
        (n ? '<small>' + n + '</small>' : '') + '</div><small>' + '一二三四五六日'[i] + '</small></div>').join('') +
      '</div>' +
      '<div class="f-label" style="margin-top:14px">本周课程构成</div>' +
      '<div class="stat-list">' + (names.length ? names.map(k =>
        '<div class="stat-row"><span class="stat-name">' + esc(k) + '</span>' +
        '<span class="stat-val">' + byName[k].n + ' 次 · ' + byName[k].secs + ' 节' +
        (byName[k].loc ? ' · ' + esc(byName[k].loc) : '') + '</span></div>').join('')
        : '<p class="sub">本周没有课 🎉</p>') +
      '</div></div>';
  },
};

js/update.js.c:
/* update.js — 自动更新：GitHub 托管清单 → 网页层热更新 / 原生层装包提示 + 更新说明弹窗
 * 托管仓库：Tim-JoJo/duomi-web（public）
 * version.json：{ web, native, name, notes[], bundle, apk }
 * 网页资源经 api.github.com 拉取（无 CDN 缓存延迟，大陆可达），失败静默跳过不影响离线使用
 */
'use strict';

const WEB_VERSION = 18;   // 网页层版本号：每次热更新 +1（publish.sh 自动维护）
const UPDATE_MANIFEST = 'https://api.github.com/repos/Tim-JoJo/duomi-web/contents/version.json';
const UPDATE_TIMEOUT = 3000;

const Update = {
  manifestUrl() {
    // 测试/镜像可覆盖：localStorage.upd_url
    try { const o = localStorage.getItem('upd_url'); if (o) return o; } catch (e) {}
    return UPDATE_MANIFEST;
  },

  b64ToText(b64) {
    const bin = atob(b64.replace(/\s/g, ''));
    const bytes = Uint8Array.from(bin, c => c.charCodeAt(0));
    return new TextDecoder('utf-8').decode(bytes);
  },

  async fetchManifest() {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), UPDATE_TIMEOUT);
    try {
      const res = await fetch(this.manifestUrl(), { cache: 'no-store', signal: ctrl.signal });
      if (!res.ok) return null;
      const j = await res.json();
      if (!j) return null;
      if (j.content) return JSON.parse(this.b64ToText(j.content));   // GitHub API 信封
      if (j.web) return j;                                            // 裸 JSON（镜像/测试）
    } catch (e) { return null; }
    finally { clearTimeout(timer); }
  },

  localWeb() { return +(Store.getPref('web_version', String(WEB_VERSION))); },
  nativeVer() {
    try { return (window.AndroidBridge && AndroidBridge.nativeVersionCode) ? +(AndroidBridge.nativeVersionCode() || 0) : 0; }
    catch (e) { return 0; }
  },

  async check() {
    if (!Store.getPref) return;                    // 过早调用保护
    if (/PLACEHOLDER/.test(this.manifestUrl())) return;
    const m = await this.fetchManifest();
    if (!m || !m.web) return;
    this.saveNotes(m);

    const localWeb = this.localWeb();
    const nativeVer = this.nativeVer();

    // 1) 网页层热更新（仅 Android WebView 有落盘桥）
    if (m.web > localWeb && m.bundle && window.AndroidBridge && typeof AndroidBridge.applyHotUpdate === 'function') {
      try {
        const b = await (await fetch(m.bundle, { cache: 'no-store' })).json();
        if (b && b.files && Object.keys(b.files).length) {
          Store.setPref('web_version', String(m.web));
          this.saveNotes(m);
          try {
            const rs = await navigator.serviceWorker.getRegistrations();
            for (const r of rs) await r.unregister();
            const ks = await caches.keys();
            for (const k of ks) await caches.delete(k);
          } catch (e) {}
          AndroidBridge.applyHotUpdate(JSON.stringify({ version: String(m.web), files: b.files }));
          return;                                   // 原生写盘后自动 reload，新页面弹出更新说明
        }
      } catch (e) { /* 下载失败静默，下次再试 */ }
    }

    // 2) 原生层更新：提示下载新 APK
    if (nativeVer && m.native > nativeVer && m.apk) {
      this.showModal('发现新版本 v' + (m.name || m.native), m.notes, '更新需要安装新安装包，桌面图标与全部数据保持不变', m.apk);
      return;
    }

    // 3) 刚完成热更新 / 版本标记变化 → 更新说明弹窗（每次版本只弹一次）
    const seen = Store.getPref('seen_notes', '');
    const notes = Store.getPref('update_notes', '');
    if (localWeb !== WEB_VERSION && !this._modalShown) {
      // 本地代码已是最新（WEB_VERSION），但没见过当前版本说明
      if (notes) this.showModal('已更新 · v' + (m.name || ('web' + WEB_VERSION)), JSON.parse(notes), null);
      Store.setPref('seen_notes', String(WEB_VERSION));
      Store.setPref('web_version', String(Math.max(localWeb, WEB_VERSION)));
    } else if (notes && seen !== String(WEB_VERSION)) {
      this.showModal('已更新 · v' + (m.name || ('web' + WEB_VERSION)), JSON.parse(notes), null);
      Store.setPref('seen_notes', String(WEB_VERSION));
    }
  },

  saveNotes(m) {
    if (m && Array.isArray(m.notes) && m.notes.length) {
      Store.setPref('update_notes', JSON.stringify(m.notes));
      if (m.name) Store.setPref('update_name', m.name);
    }
  },

  showModal(title, notes, apkUrl) {
    if (this._modalShown) return;
    this._modalShown = true;
    const old = document.getElementById('updModal');
    if (old) old.remove();
    const el = document.createElement('div');
    el.id = 'updModal';
    const list = (notes || []).map(n => '<li>' + esc(n) + '</li>').join('') || '<li>体验优化与问题修复</li>';
    el.innerHTML = '<div class="upd-card">' +
      '<div class="upd-badge">🎉</div>' +
      '<h3 class="upd-title">' + esc(title) + '</h3>' +
      '<ul class="upd-notes">' + list + '</ul>' +
      '<div class="upd-btns">' +
      (apkUrl ? '<button class="primary-btn wide" id="updDl" type="button">下载新版本</button>' : '') +
      '<button class="ghost-btn wide" id="updClose" type="button">知道了</button>' +
      '</div></div>';
    document.body.appendChild(el);
    requestAnimationFrame(() => el.classList.add('show'));
    el.addEventListener('click', (e) => {
      if (e.target === el || e.target.id === 'updClose') {
        el.classList.remove('show');
        setTimeout(() => el.remove(), 200);
      } else if (e.target.id === 'updDl' && apkUrl) {
        location.href = apkUrl;   // 原生壳会把外部链接转给浏览器下载
      }
    });
  },
};

document.addEventListener('DOMContentLoaded', () => setTimeout(() => Update.check(), 1500));

