/* render.js — 视图渲染：Today / 时间线 / 周网格（表头 / 周次行 / 时间轴 / 课程卡片） */
'use strict';

const Render = {
  /** 渲染周网格表头：日期标题 + 第 N 周 + 星期 + 当前课表名 + 回本周胶囊 */
  renderHeader(state) {
    document.getElementById('dateTitle').textContent = formatCN(state.today);
    document.getElementById('weekNum').textContent = state.viewWeek;
    document.getElementById('weekDayName').textContent = WEEKDAY_NAMES[(state.today.getDay() + 6) % 7];
    const sch = Store.active();
    const pill = document.getElementById('schNamePill');
    if (sch) {
      pill.innerHTML = '<span>' + esc(sch.name) + '</span> ›';
      pill.hidden = false;
    } else pill.hidden = true;
    // 「回到本周」胶囊：查看非当前周时显示
    const nwp = document.getElementById('nowWeekPill');
    if (nwp) nwp.hidden = state.viewWeek === state.curWeek;
  },

  /** Today / 时间线 头部日期行 */
  renderPageHeads(state) {
    const dl = document.getElementById('todayDateLine');
    if (dl) dl.textContent = WEEKDAY_NAMES[(state.today.getDay() + 6) % 7] + ' · ' + formatCN(state.today);
    const tl = document.getElementById('tlDateLine');
    if (tl) {
      const mon = addDays(state.weekMonday, 0), sun = addDays(state.weekMonday, 6);
      tl.textContent = '第 ' + state.viewWeek + ' 周 · ' + (mon.getMonth() + 1) + '.' + mon.getDate() + ' - ' + (sun.getMonth() + 1) + '.' + sun.getDate();
    }
  },

  /** Today 视图：下一节课高亮卡 + 剩余课程（按 上午/下午/晚上 分组） */
  renderTodayView(state) {
    const info = App.todayInfo();
    const nextWrap = document.getElementById('todayNextCard');
    const restWrap = document.getElementById('todayRest');
    if (!nextWrap || !restWrap) return;
    if (!info || !info.list.length) {
      nextWrap.innerHTML = '<div class="rr-empty">今天没有课，享受自由吧 🎉</div>';
      restWrap.innerHTML = '';
      return;
    }
    const now = new Date();
    const h = now.getHours();
    const seg = h < 12 ? '上午' : h < 18 ? '下午' : '晚上';
    const parts = { '上午': [], '下午': [], '晚上': [] };
    for (const c of info.list) {
      const sh = parseInt(c.timeStr, 10) || 0;
      (sh < 12 ? parts['上午'] : sh < 18 ? parts['下午'] : parts['晚上']).push(c);
    }
    // 下一节/进行中 高亮卡
    if (info.nowCourse || info.nextCourse) {
      const c = info.nowCourse || info.nextCourse;
      const isNow = !!info.nowCourse;
      const meta = isNow
        ? esc(c.loc || '未填写地点') + ' · ' + c.endStr + ' 下课'
        : esc(c.loc || '未填写地点') + ' · ' + c.timeStr + '~' + c.endStr;
      nextWrap.innerHTML =
        '<button class="next-card" id="nextCard" type="button" style="--cc:var(--c' + c.color + '-bar)">' +
        '<div style="flex:1;min-width:0">' +
        '<div class="nc-label">⏱ ' + (isNow ? '进行中' : '下一节课') + '</div>' +
        '<div class="nc-name">' + esc(c.name) + '</div>' +
        '<div class="nc-meta">📍 ' + meta + '</div></div>' +
        '<span class="nc-arrow">›</span></button>';
      nextWrap.querySelector('#nextCard').addEventListener('click', () => Render.showCoursePop(c.id));
    } else {
      nextWrap.innerHTML = '<div class="rr-empty">今天 ' + info.list.length + ' 节课都结束啦 ✓</div>';
    }
    // 剩余课程分组
    let html = '';
    for (const key of ['上午', '下午', '晚上']) {
      const arr = parts[key];
      if (!arr.length) continue;
      if (key === seg) {
        html += '<div class="rest-sec"><div class="rest-head"><span class="rest-title">剩余课程</span></div>' + this.restRows(arr) + '</div>';
        break; // 只显示当前时段起之后的组（含当前组）
      }
    }
    if (!html) {
      // 当前时段之后的组都没有了 → 显示全天列表
      html = '<div class="rest-sec"><div class="rest-head"><span class="rest-title">今日全部</span></div>' + this.restRows(info.list) + '</div>';
    }
    restWrap.innerHTML = html;
    this.bindRestRows(restWrap);
  },

  restRows(list) {
    return '<div class="rest-list">' + list.map(c => {
      const cls = c.status === 'now' ? ' now' : c.status === 'done' ? ' done' : '';
      const badge = c.minsToStart == null ? ''
        : c.status === 'now' ? '<span class="rr-badge">进行中</span>'
        : c.status === 'done' ? '<span class="rr-badge done">已下课</span>'
        : '<span class="rr-badge">' + (c.minsToStart >= 60 ? Math.floor(c.minsToStart / 60) + '时' + (c.minsToStart % 60 ? (c.minsToStart % 60) + '分' : '') : c.minsToStart + '分') + '后</span>';
      return '<button class="rest-row' + cls + '" data-cid="' + c.id + '" type="button">' +
        '<span class="rr-time"><b>' + c.timeStr + '</b><small>' + c.endStr + '</small></span>' +
        '<span class="rr-bar" style="--rc:var(--c' + c.color + '-bar)"></span>' +
        '<span class="rr-main"><span class="rr-name">' + esc(c.name) + '</span>' +
        '<span class="rr-meta">' + esc(c.loc || '未填写地点') + ' · 第' + c.p1 + '-' + c.p2 + '节' + (c.teacher ? ' · ' + esc(c.teacher) : '') + '</span></span>' +
        badge + '</button>';
    }).join('') + '</div>';
  },

  bindRestRows(wrap) {
    for (const b of wrap.querySelectorAll('.rest-row[data-cid]')) {
      b.addEventListener('click', () => Render.showCoursePop(b.dataset.cid));
    }
  },

  /** 时间线视图：本周逐日课程列表 */
  renderTimeline(state) {
    const body = document.getElementById('timelineBody');
    if (!body) return;
    const sch = Store.active();
    if (!sch) { body.innerHTML = '<div class="rr-empty">还没有课表，先去「我的」导入一个吧</div>'; return; }
    const periods = state.periods || PERIODS;
    const nowMin = state.today.getHours() * 60 + state.today.getMinutes();
    const todayInWeek = sameDay(mondayOf(state.today), state.weekMonday);
    const todayIdx = (state.today.getDay() + 6) % 7;
    let html = '';
    for (let d = 0; d < 7; d++) {
      const date = addDays(state.weekMonday, d);
      const isToday = todayInWeek && d === todayIdx;
      const courses = sch.courses
        .filter(c => c.day === d + 1 && (!c.weeks || !c.weeks.length || c.weeks.includes(state.viewWeek)))
        .sort((a, b) => a.p1 - b.p1 || a.p2 - b.p2)
        .map(c => {
          const ps = periods[c.p1 - 1], pe = periods[c.p2 - 1];
          const s = minutesOf(ps.start), e = minutesOf(pe.end);
          return Object.assign({}, c, { timeStr: ps.start, endStr: pe.end, status: !isToday ? 'todo' : (nowMin < s ? 'todo' : (nowMin <= e ? 'now' : 'done')), minsToStart: isToday ? (s - nowMin) : null });
        });
      html += '<div class="rest-sec"><div class="tl-dayhead' + (isToday ? ' today' : '') + '"><b>周' + '一二三四五六日'[d] + '</b><small>' + (date.getMonth() + 1) + '.' + date.getDate() + (isToday ? ' · 今天' : '') + ' · ' + courses.length + ' 节</small></div>' +
        (courses.length ? this.restRows(courses) : '<div class="rr-empty" style="padding:10px 0">没有课</div>') + '</div>';
    }
    body.innerHTML = html;
    this.bindRestRows(body);
  },

  /** 渲染星期表头行：月份格 + 周一~周日 */
  renderWeekbar(state) {
    const el = document.getElementById('weekbar');
    const weekMonday = addDays(state.weekMonday, 0);
    const month = weekMonday.getMonth() + 1;
    let html = '<div class="wb-month">' + month + '<small>月</small></div>';
    const todayInWeek = sameDay(mondayOf(state.today), state.weekMonday);
    for (let i = 0; i < 7; i++) {
      const d = addDays(weekMonday, i);
      const isToday = todayInWeek && sameDay(d, state.today);
      const weekend = i >= 5;
      html += '<div class="wb-day' + (weekend ? ' weekend' : '') + (isToday ? ' today' : '') + '" data-i="' + i + '">' +
        '<div class="wd">' + WEEKDAY_NAMES[i] + '</div>' +
        '<div class="dn">' + d.getDate() + '</div></div>';
    }
    el.innerHTML = html;
  },

  /** 渲染左侧时间轴（节次号 + 起止时间 + 当前节高亮） */
  renderTimeCol(state) {
    const el = document.getElementById('timeCol');
    const rowH = state.rowH;
    const periods = state.periods || PERIODS;
    const nowMin = state.today.getHours() * 60 + state.today.getMinutes();
    const showNow = sameDay(mondayOf(state.today), state.weekMonday) && state.viewWeek === state.curWeek;
    let cur = -1;
    if (showNow) {
      for (const p of periods) {
        if (nowMin >= minutesOf(p.start) && nowMin <= minutesOf(p.end)) { cur = p.n; break; }
      }
    }
    let html = '';
    for (const p of periods) {
      const top = (p.n - 1) * rowH;
      html += '<div class="time-cell' + (p.n === cur ? ' now' : '') + '" style="top:' + top + 'px;height:' + rowH + 'px">' +
        '<div class="tn">' + p.n + '</div>' +
        '<div class="tt">' + p.start + '</div>' +
        '<div class="tt">' + p.end + '</div>' +
        '</div>';
    }
    el.innerHTML = html;
  },

  /** 渲染 7 天列容器骨架（5天模式隐藏周末列） */
  renderDayCols(state) {
    const el = document.getElementById('daysGrid');
    const vw = document.getElementById('vwGrid');
    const days = Store.getPref('gridDays', '7') === '5' ? 5 : 7;
    if (vw) vw.classList.toggle('d5', days === 5);
    el.style.height = (PERIODS.length * state.rowH) + 'px';
    let html = '';
    for (let i = 0; i < 7; i++) {
      html += '<div class="day-col" data-day="' + (i + 1) + '"></div>';
    }
    el.innerHTML = html;
  },

  /**
   * 渲染课程卡片：节次跨行定位 / 同日冲突并排 / 非本周淡显
   * gridScope=week 只显示本周课程；=all 额外淡显其他周课程（角标显示周次）
   */
  renderCourses(state) {
    const sch = Store.active();
    const emptyEl = document.getElementById('emptyState');
    if (!sch) { emptyEl.hidden = false; return; }
    emptyEl.hidden = true;

    const rowH = state.rowH;
    const scope = Store.getPref('gridScope', 'all');
    // day → 该周课程列表（本周正式 + 非本周淡显）
    const byDay = {}, ghostByDay = {};
    for (let d = 1; d <= 7; d++) { byDay[d] = []; ghostByDay[d] = []; }
    for (const c of sch.courses) {
      const inWeek = !c.weeks || c.weeks.length === 0 || c.weeks.includes(state.viewWeek);
      (inWeek ? byDay : ghostByDay)[c.day].push(c);
    }

    const dayHtml = {};
    for (let d = 1; d <= 7; d++) {
      dayHtml[d] = this.renderDayCards(byDay[d], rowH, false)
        + (scope === 'all' ? this.renderDayCards(ghostByDay[d], rowH, true) : '');
    }

    // 写入对应列
    const cols = document.querySelectorAll('#daysGrid .day-col');
    for (const col of cols) {
      const d = +col.getAttribute('data-day');
      col.innerHTML = dayHtml[d] || '';
      for (const el of col.querySelectorAll('.course')) {
        el.addEventListener('click', () => Render.showCoursePop(el.dataset.cid));
      }
    }
  },

  /** 一天的课程 → 卡片 HTML（重叠分组的并排布局） */
  renderDayCards(courses, rowH, ghost) {
    if (!courses || !courses.length) return '';
    // 按节次重叠分组
    const sorted = courses.slice().sort((a, b) => a.p1 - b.p1 || a.p2 - b.p2);
    const groups = [];
    for (const c of sorted) {
      const g = groups.find(grp => grp.some(x => c.p1 <= x.p2 && x.p1 <= c.p2));
      if (g) g.push(c); else groups.push([c]);
    }
    let html = '';
    for (const g of groups) {
      const n = g.length;
      g.forEach((c, i) => {
        const top = (c.p1 - 1) * rowH;
        const h = (c.p2 - c.p1 + 1) * rowH - 3;
        const left = n > 1 ? 'left:calc(' + (i * 100 / n) + '% + 1.5px);right:calc(' + (100 - (i + 1) * 100 / n) + '% + 1px);' : 'left:1.5px;right:1.5px;';
        html += '<div class="course' + (ghost ? ' ghost' : '') + '" data-cid="' + c.id + '" style="' + left +
          'top:' + top + 'px;height:' + h + 'px">' +
          '<div class="bar" style="background:var(--c' + c.color + '-bar)"></div>' +
          (ghost ? '<span class="badge" style="background:var(--c' + c.color + '-bar);color:#fff">第' + (c.weeks && c.weeks.length ? c.weeks[0] : '?') + '周</span>' : '') +
          '<div class="cname">' + esc(c.name) + '</div>' +
          (c.loc ? '<div class="cloc">' + esc(c.loc) + '</div>' : '') +
          '</div>';
      });
    }
    return html;
  },

  /** 课程详情弹层（含返回键跟踪） */
  showCoursePop(cid) {
    const sch = Store.active();
    if (!sch) return;
    const c = sch.courses.find(x => x.id === cid);
    if (!c) return;
    const old = document.getElementById('coursePop');
    if (old) { if (old._rec) old._rec.close(); else old.remove(); }
    const periods = Store.periodsOf(sch);
    const p1t = periods[c.p1 - 1], p2t = periods[c.p2 - 1];
    const weeksTxt = !c.weeks || !c.weeks.length ? '每周' :
      (function () {
        const mode = CourseEditor.detectMode(c.weeks);
        const prefix = mode === 'odd' ? '单周 · ' : mode === 'even' ? '双周 · ' : '';
        return prefix + toRangeText(c.weeks);
      })();
    const el = document.createElement('div');
    el.id = 'coursePop';
    el.className = 'course-pop';
    el.innerHTML = '<div class="pop-card">' +
      '<div class="p-name">' + esc(c.name) + '</div>' +
      '<div class="p-rows">' +
      rowHtml('地点', c.loc ? c.loc : '—') +
      (c.teacher ? rowHtml('老师', c.teacher) : '') +
      rowHtml('时间', '周' + '一二三四五六日'[c.day - 1] + ' · 第' + c.p1 + '-' + c.p2 + '节') +
      rowHtml('节次', p1t.start + ' ~ ' + p2t.end) +
      rowHtml('周次', weeksTxt) +
      '</div>' +
      '<button class="pop-edit" id="popEditBtn">编辑课程</button>' +
      '<button class="pop-close">关闭</button></div>';
    const rec = App.trackOverlay(() => el.remove());
    el._rec = rec;
    el.addEventListener('click', (e) => {
      if (e.target === el || e.target.classList.contains('pop-close')) rec.close();
      else if (e.target.id === 'popEditBtn') { rec.close(); CourseEditor.open(c.id); }
    });
    document.body.appendChild(el);

    function rowHtml(k, v) { return '<div class="p-row"><span class="p-k">' + k + '</span><span class="p-v">' + esc(v) + '</span></div>'; }
  },

  /** 整帧渲染 */
  renderAll(state) {
    this.renderPageHeads(state);
    this.renderHeader(state);
    this.renderWeekbar(state);
    this.renderTimeCol(state);
    this.renderDayCols(state);
    this.renderCourses(state);
    this.renderTodayView(state);
    this.renderTimeline(state);
    if (typeof Extras !== 'undefined') Extras.renderCdChips();
  },
};

