/* textimport.js — 粘贴文本导入：教务系统/通知里复制的课表文字 → 启发式解析 → 预览确认
 * 复用 ocr.js 的 parseScheduleText 与预览 UI，全程离线。
 */
'use strict';

const TextImport = {
  open() {
    const old = document.getElementById('tiSheet');
    if (old) old.remove();
    const el = document.createElement('div');
    el.id = 'tiSheet';
    el.innerHTML = '<div class="sheet-mask show"></div>' +
      '<div class="sheet show">' +
      '<div class="sheet-grip"></div>' +
      '<h2>粘贴文本导入</h2>' +
      '<p class="sub">把教务系统、通知或聊天里的课表文字粘贴到下面，<b>每行一门课</b>，行内带上星期和节次，例如：<br>高等数学 周一 第1-2节 理教A101（单周）</p>' +
      '<textarea id="tiText" class="f-input ti-area" rows="9" placeholder="高等数学 A(1) 周一 第1-2节 理教 A101&#10;数据结构 周二 3-4节 理教 B201&#10;大学英语 III 周五 5-6节 外语楼305 双周"></textarea>' +
      '<div class="f-btns">' +
      '<button class="ghost-btn wide" id="tiCancel">取消</button>' +
      '<button class="primary-btn wide" id="tiParse">解析课程</button>' +
      '</div></div>';
    document.body.appendChild(el);
    const rec = App.trackOverlay(() => el.remove());
    el.querySelector('.sheet-mask').addEventListener('click', () => rec.close());
    el.querySelector('#tiCancel').addEventListener('click', () => rec.close());
    el.querySelector('#tiParse').addEventListener('click', () => {
      const lines = el.querySelector('#tiText').value.split(/\n+/).map(s => s.trim()).filter(Boolean);
      if (!lines.length) { toast('先把课表文字粘贴进来', 'err'); return; }
      const parsed = parseScheduleText(lines);
      if (!parsed.length) {
        toast('没有解析出课程：每行需含星期（如 周一）和节次（如 1-2节）', 'err');
        return;
      }
      rec.close();
      const now = new Date();
      OcrImporter.showPreview(parsed, {
        title: '解析结果',
        defaultName: '导入课表 ' + (now.getMonth() + 1) + '月' + now.getDate() + '日',
      });
    });
    el.querySelector('#tiText').focus();
  },
};

