/* schedules.js — 多课表管理：切换 / 重命名 / 删除 / 开学日 / 导出 ICS */
'use strict';

const Schedules = {
  init() {
    // 齿轮/课表名入口由 app.js 绑定到「我的」Tab；这里只挂导出
    document.getElementById('btnExport').addEventListener('click', () => this.exportCurrent());
  },

  /** 「我的」常驻页 */
  renderMe() {
    const sheet = document.getElementById('meBody');
    const sch = Store.active();
    let html = '<div class="page-body"><p class="sub">点按课表切换查看；数据保存在本机浏览器。</p>';

    html += Store.data.schedules.map(s => {
      const cur = s.id === Store.data.activeId;
      return '<div class="sch-item' + (cur ? ' current' : '') + '" data-id="' + s.id + '" data-act="switch">' +
        '<div class="sch-swatch" style="background:var(--c' + (s.colorIdx || 0) + '-bg);color:var(--c' + (s.colorIdx || 0) + '-ink)">' + esc(s.name.slice(0, 1)) + '</div>' +
        '<div class="sch-meta"><div class="sch-name">' + esc(s.name) + '</div>' +
        '<div class="sch-info">' + s.courses.length + ' 门课 · 开学 ' + (s.semesterStart || '').slice(5) + (cur ? ' · 当前' : '') + '</div></div>' +
        '<div class="sch-acts">' +
        '<button class="sch-act" data-act="rename" title="重命名"><svg viewBox="0 0 24 24" width="16" height="16"><path d="M4 20h4L19 9l-4-4L4 16v4zM13.5 6.5l4 4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg></button>' +
        '<button class="sch-act danger" data-act="del" title="删除"><svg viewBox="0 0 24 24" width="16" height="16"><path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 11v6M14 11v6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg></button>' +
        '</div></div>';
    }).join('');

    if (!Store.data.schedules.length) {
      html += '<p class="sub" style="text-align:center;padding:20px 0">还没有课表，先导入一个吧</p>';
    }

    html += '<div class="import-row">' +
      '<button class="primary-btn" data-act="import">＋ 导入课表文件</button>' +
      '<button class="ghost-btn wide" style="margin-top:0" data-act="addcourse">＋ 手动添加课程</button>' +
      '</div>' +
      '<div class="import-row">' +
      '<button class="ghost-btn wide" style="margin-top:0" data-act="ocr">📷 图片 / PDF 识别导入</button>' +
      '<button class="ghost-btn wide" style="margin-top:0" data-act="textimport">📋 粘贴文本导入</button>' +
      '</div>' +
      (sch ? '<div class="import-row">' +
      '<button class="ghost-btn wide" style="margin-top:0" data-act="stats">📊 课程统计</button>' +
      '<button class="ghost-btn wide" style="margin-top:0" data-act="shareimg">📤 分享课表长图</button>' +
      '</div>' : '');

    // ── 外观 ──
    const theme = Store.getPref('theme', 'auto');
    html += '<details class="sec"><summary>🎨 外观</summary><div class="sec-body">' +
      '<div class="f-label">深色模式</div><div class="chips" id="themeChips">' +
      [['auto', '跟随系统'], ['light', '浅色'], ['dark', '深色']].map(kv =>
        '<button type="button" class="chip' + (theme === kv[0] ? ' on' : '') + '" data-theme="' + kv[0] + '">' + kv[1] + '</button>').join('') +
      '</div>' +
      '<div class="f-label" style="margin-top:10px">界面材质</div><div class="chips" id="glassChips">' +
      [['auto', '跟随系统'], ['clear', '清透玻璃'], ['frost', '磨砂玻璃'], ['classic', '经典毛玻璃']].map(kv =>
        '<button type="button" class="chip' + ((Store.getPref('material', '') || Store.getPref('glass', 'auto')) === kv[0] ? ' on' : '') + '" data-glass="' + kv[0] + '">' + kv[1] + '</button>').join('') +
      '</div>' +
      '<p class="sub" style="margin-top:6px">自动=不支持的设备自动转经典材质</p>' +
      '<div class="f-label" style="margin-top:10px">背景色</div>' +
      '<div class="bg-row"><input type="color" id="bgColor" value="' + Store.getPref('bgcolor', document.documentElement.classList.contains('dark') ? '#141922' : '#EDF2FB') + '">' +
      '<button type="button" class="chip" id="bgReset">默认</button></div>' +
      '</div></details>';

    // ── 节次时间 ──
    if (sch) {
      const periods = Store.periodsOf(sch);
      html += '<details class="sec"><summary>⏰ 节次时间</summary><div class="sec-body"><div id="periodRows">' +
        periods.map(p =>
          '<div class="pedit-row"><span class="pedit-n">' + p.n + '</span>' +
          '<input type="time" class="pedit-t" data-k="start" value="' + p.start + '">' +
          '<span class="f-sep">~</span>' +
          '<input type="time" class="pedit-t" data-k="end" value="' + p.end + '"></div>').join('') +
        '</div><div class="f-btns">' +
        '<button class="primary-btn wide" id="periodSave">保存节次</button>' +
        '<button class="ghost-btn wide" id="periodReset">恢复默认</button>' +
        '</div></div></details>';
    }

    // ── 备份与恢复 ──
    html += '<details class="sec"><summary>💾 备份与恢复</summary><div class="sec-body">' +
      '<p class="sub" style="margin-bottom:8px">备份包含全部课表与设置，可跨设备迁移。</p>' +
      '<div class="import-row">' +
      '<button class="primary-btn wide" style="margin-top:0" id="backupExport">导出备份</button>' +
      '<button class="ghost-btn wide" style="margin-top:0" id="backupImportBtn">导入备份</button>' +
      '</div><input type="file" id="backupImport" accept=".json,application/json" hidden>' +
      '</div></details>';

    // ── 课程提醒（Android App 内可用） ──
    if (window.AndroidBridge && typeof AndroidBridge.setReminders === 'function') {
      let rem = {};
      try { rem = JSON.parse(Store.getPref('reminders', '') || '{}'); } catch (e) {}
      if (rem.enabled === undefined) rem.enabled = false;
      if (!rem.lead) rem.lead = 10;
      const leadChoices = [5, 10, 15, 20, 30];
      if (!leadChoices.includes(rem.lead)) leadChoices.push(rem.lead);
      leadChoices.sort((a, b) => a - b);
      html += '<details class="sec"><summary>🔔 课程提醒</summary><div class="sec-body">' +
        '<div class="f-label">上课前提醒</div><div class="chips" id="remToggles">' +
        '<button type="button" class="chip' + (rem.enabled ? ' on' : '') + '" data-on="1">开启提醒</button>' +
        '<button type="button" class="chip' + (!rem.enabled ? ' on' : '') + '" data-on="0">关闭</button>' +
        '</div>' +
        '<div class="f-label" style="margin-top:10px">提前</div><div class="chips" id="remLead">' +
        leadChoices.map(n => '<button type="button" class="chip' + (rem.lead === n ? ' on' : '') + '" data-lead="' + n + '">' + n + ' 分钟</button>').join('') +
        '<button type="button" class="chip" data-lead="custom">自定义…</button>' +
        '</div><p class="sub" style="margin-top:8px">按当前课表「' + esc(sch ? sch.name : '') + '」排定，改动课表后自动更新。</p>' +
        '</div></details>';
    }

    // ── 上课静音（Android App 内可用） ──
    if (window.AndroidBridge && typeof AndroidBridge.setMute === 'function') {
      let mute = {};
      try { mute = JSON.parse(Store.getPref('mute', '') || '{}'); } catch (e) {}
      if (mute.enabled === undefined) mute.enabled = false;
      html += '<details class="sec"><summary>🔇 上课静音</summary><div class="sec-body">' +
        '<div class="f-label">上课期间手机静音</div><div class="chips" id="muteToggles">' +
        '<button type="button" class="chip' + (mute.enabled ? ' on' : '') + '" data-m="1">开启</button>' +
        '<button type="button" class="chip' + (!mute.enabled ? ' on' : '') + '" data-m="0">关闭</button>' +
        '</div><p class="sub" style="margin-top:8px">上课自动震动静音、下课后恢复。首次开启需在系统设置中允许「勿扰权限」。</p>' +
        '<button class="ghost-btn wide" id="mutePolicyBtn" style="margin-top:4px">打开勿扰权限设置</button>' +
        '</div></details>';
    }

    // ── 倒计时 ──
    html += '<details class="sec" id="cdSection"><summary>🎯 倒计时</summary><div class="sec-body">' +
      (typeof Extras !== 'undefined' ? Extras.cdSectionHtml() : '') +
      '</div></details>';

    // ── 关于 ──
    html += '<details class="sec"><summary>ℹ️ 关于</summary><div class="sec-body">' +
      '<p class="sub" style="margin:0 0 6px">哆米的课程表 v1.8</p>' +
      '<p class="sub" style="margin:0">课表数据默认仅保存在本机，不上传、不联网同步。</p>' +
      '</div></details>';

    if (sch) {
      html += '<div class="sem-row"><label>开学日期（第 1 周周一）</label>' +
        '<input type="date" id="semStartInput" value="' + esc(sch.semesterStart || '') + '"></div>';
    }

    html += '</div>';
    sheet.innerHTML = html;

    // 事件
    for (const el of sheet.querySelectorAll('[data-act]')) {
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        const act = el.dataset.act;
        const item = el.closest('.sch-item');
        const id = (item || el).dataset.id;
        if (act === 'switch') { this.switchTo(id); }
        else if (act === 'rename') { this.rename(id); }
        else if (act === 'del') { this.remove(id); }
        else if (act === 'import') { Importer.pick(); }
        else if (act === 'addcourse') { CourseEditor.open(); }
        else if (act === 'ocr') { OcrImporter.pick(); }
        else if (act === 'textimport') { if (typeof TextImport !== 'undefined') TextImport.open(); }
        else if (act === 'shareimg') { if (typeof ShareCard !== 'undefined') ShareCard.export(); }
      });
    }
    const semInput = document.getElementById('semStartInput');
    if (semInput) {
      semInput.addEventListener('change', () => {
        const v = semInput.value;
        if (!v) return;
        const d = parseISO(v);
        if (d.getDay() !== 1) { toast('开学日期需要是周一', 'err'); semInput.value = Store.active().semesterStart; return; }
        Store.setSemesterStart(Store.data.activeId, v);
        App.initState();
        App.refresh();
        toast('开学日期已更新', 'ok');
      });
    }

    // ── 外观 ──
    const themeChips = document.getElementById('themeChips');
    if (themeChips) {
      themeChips.addEventListener('click', (e) => {
        const b = e.target.closest('[data-theme]'); if (!b) return;
        Store.setPref('theme', b.dataset.theme);
        App.applyTheme();
        themeChips.querySelectorAll('.chip').forEach(x => x.classList.toggle('on', x === b));
      });
      const bgColor = document.getElementById('bgColor');
      bgColor.addEventListener('change', () => {
        Store.setPref('bgcolor', bgColor.value);
        App.applyTheme();
      });
      const glassChips = document.getElementById('glassChips');
      if (glassChips) {
        glassChips.addEventListener('click', (e) => {
          const b = e.target.closest('[data-glass]'); if (!b) return;
          Store.setPref('material', b.dataset.glass);
          App.applyGlass();
          glassChips.querySelectorAll('.chip').forEach(x => x.classList.toggle('on', x === b));
        });
      }
      document.getElementById('bgReset').addEventListener('click', () => {
        try { localStorage.removeItem('kb_pref_bgcolor'); } catch (e) {}
        Store.setPref('bgcolor', '');
        App.applyTheme();
        toast('背景色已恢复默认', 'ok');
      });
    }

    // ── 节次时间 ──
    const periodSave = document.getElementById('periodSave');
    if (periodSave) {
      periodSave.addEventListener('click', () => {
        const arr = [];
        for (const row of document.querySelectorAll('#periodRows .pedit-row')) {
          arr.push({
            start: row.querySelector('[data-k="start"]').value,
            end: row.querySelector('[data-k="end"]').value,
          });
        }
        if (arr.some(p => !p.start || !p.end || p.start >= p.end)) { toast('节次时间格式不对', 'err'); return; }
        if (Store.setPeriods(Store.data.activeId, arr)) {
          App.initState();
          App.refresh();
          toast('节次时间已保存', 'ok');
          this.renderMe();
        } else toast('保存失败', 'err');
      });
      document.getElementById('periodReset').addEventListener('click', () => {
        Store.resetPeriods(Store.data.activeId);
        App.initState();
        App.refresh();
        this.renderMe();
        toast('已恢复默认节次时间', 'ok');
      });
    }

    // ── 课程提醒 chips ──
    const remToggles = document.getElementById('remToggles');
    if (remToggles) {
      const pushRem = () => Schedules.pushReminders();
      const upd = () => {
        remToggles.querySelectorAll('[data-on]').forEach(x =>
          x.classList.toggle('on', (x.dataset.on === '1') === Schedules.remCfg().enabled));
        document.querySelectorAll('#remLead .chip').forEach(x =>
          x.classList.toggle('on', +x.dataset.lead === Schedules.remCfg().lead));
      };
      remToggles.addEventListener('click', (e) => {
        const b = e.target.closest('[data-on]'); if (!b) return;
        const cfg = Schedules.remCfg();
        cfg.enabled = b.dataset.on === '1';
        Store.setPref('reminders', JSON.stringify(cfg));
        upd(); pushRem();
      });
      document.getElementById('remLead').addEventListener('click', (e) => {
        const b = e.target.closest('[data-lead]'); if (!b) return;
        const cfg = Schedules.remCfg();
        if (b.dataset.lead === 'custom') {
          const v = prompt('上课前多少分钟提醒？（5-180）', String(cfg.lead));
          if (v == null) return;
          const n = Math.round(+v);
          if (!n || n < 5 || n > 180) { toast('请输入 5-180 之间的分钟数', 'err'); return; }
          cfg.lead = n;
        } else {
          cfg.lead = +b.dataset.lead;
        }
        Store.setPref('reminders', JSON.stringify(cfg));
        upd(); pushRem();
      });
      upd();
    }

    // ── 上课静音 ──
    const muteToggles = document.getElementById('muteToggles');
    if (muteToggles) {
      const updMute = () => muteToggles.querySelectorAll('[data-m]').forEach(x =>
        x.classList.toggle('on', (x.dataset.m === '1') === (Schedules.muteCfg().enabled)));
      muteToggles.addEventListener('click', (e) => {
        const b = e.target.closest('[data-m]'); if (!b) return;
        const cfg = Schedules.muteCfg();
        cfg.enabled = b.dataset.m === '1';
        Store.setPref('mute', JSON.stringify(cfg));
        if (window.AndroidBridge && typeof AndroidBridge.setMute === 'function') {
          AndroidBridge.setMute(JSON.stringify(Schedules.mutePayload()));
          if (cfg.enabled && AndroidBridge.mutePolicyGranted && !AndroidBridge.mutePolicyGranted()) {
            AndroidBridge.openMutePolicySettings();
          }
        }
        updMute();
        toast(cfg.enabled ? '上课静音已开启' : '上课静音已关闭', 'ok');
      });
      document.getElementById('mutePolicyBtn').addEventListener('click', () => {
        if (window.AndroidBridge && typeof AndroidBridge.openMutePolicySettings === 'function') AndroidBridge.openMutePolicySettings();
      });
      updMute();
    }

    // ── 倒计时区段 ──
    if (typeof Extras !== 'undefined') Extras.bindCdSection(sheet);

    // ── 备份与恢复 ──
    const backupExport = document.getElementById('backupExport');
    if (backupExport) {
      backupExport.addEventListener('click', () => {
        const payload = JSON.stringify({ app: 'duomi-schedule', version: 1, exportedAt: new Date().toISOString(), data: Store.data }, null, 2);
        const fname = '哆米课表备份-' + toISO(new Date()).replace(/-/g, '') + '.json';
        if (window.AndroidBridge && typeof AndroidBridge.exportBackup === 'function') {
          AndroidBridge.exportBackup(fname, payload);
        } else {
          const blob = new Blob([payload], { type: 'application/json' });
          const a = document.createElement('a');
          a.href = URL.createObjectURL(blob);
          a.download = fname;
          document.body.appendChild(a); a.click(); a.remove();
          setTimeout(() => URL.revokeObjectURL(a.href), 2000);
          toast('备份已导出', 'ok');
        }
      });
      const importInput = document.getElementById('backupImport');
      document.getElementById('backupImportBtn').addEventListener('click', () => importInput.click());
      importInput.addEventListener('change', () => {
        const f = importInput.files[0];
        importInput.value = '';
        if (!f) return;
        f.text().then(txt => {
          let obj;
          try { obj = JSON.parse(txt); } catch (e) { toast('不是有效的备份文件', 'err'); return; }
          if (!obj || obj.app !== 'duomi-schedule' || !obj.data || !Array.isArray(obj.data.schedules)) {
            toast('不是哆米课表的备份文件', 'err'); return;
          }
          if (!confirm('导入备份将覆盖现有全部课表（' + obj.data.schedules.length + ' 个课表），确定？')) return;
          Store.data = obj.data;
          Store.save();
          App.initState();
          App.refresh();
          this.renderMe();
          toast('已恢复备份：' + obj.data.schedules.length + ' 个课表', 'ok');
        });
      });
    }
  },

  closeSheet() { /* 「我的」为常驻页，保留空实现兼容旧调用 */ },

  switchTo(id) {
    if (id === Store.data.activeId) { this.closeSheet(); return; }
    Store.setActive(id);
    App.initStateKeepWeek();
    App.refresh();
    this.closeSheet();
    const sch = Store.active();
    if (sch) toast('已切换到「' + sch.name + '」', 'ok');
  },

  rename(id) {
    const sch = Store.data.schedules.find(s => s.id === id);
    if (!sch) return;
    const name = prompt('课表名称', sch.name);
    if (name == null) return;
    const trimmed = name.trim();
    if (!trimmed) { toast('名称不能为空', 'err'); return; }
    Store.renameSchedule(id, trimmed);
    App.refresh();
    this.renderMe();
  },

  remove(id) {
    const sch = Store.data.schedules.find(s => s.id === id);
    if (!sch) return;
    if (!confirm('删除课表「' + sch.name + '」？此操作不可恢复。')) return;
    Store.removeSchedule(id);
    App.initStateKeepWeek();
    App.refresh();
    this.closeSheet();
    toast('已删除「' + sch.name + '」', 'ok');
  },

  /** 当前课表 → ICS 文本并下载（Android 走系统保存对话框） */
  exportCurrent() {
    const sch = Store.active();
    if (!sch) { toast('还没有可导出的课表', 'err'); return; }
    const text = this.toICS(sch);
    if (window.AndroidBridge && typeof AndroidBridge.exportIcs === 'function') {
      AndroidBridge.exportIcs(sch.name.replace(/[\\/:*?"<>|]/g, '_') + '.ics', text);
      return;
    }
    try {
      const blob = new Blob([text], { type: 'text/calendar;charset=utf-8' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = sch.name.replace(/[\\/:*?"<>|]/g, '_') + '.ics';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 2000);
      toast('已导出「' + sch.name + '」（' + sch.courses.length + ' 门课）', 'ok');
    } catch (e) {
      console.error(e);
      toast('导出失败', 'err');
    }
  },

  /** 静音配置偏好 */
  muteCfg() {
    let cfg = {};
    try { cfg = JSON.parse(Store.getPref('mute', '') || '{}'); } catch (e) {}
    if (cfg.enabled === undefined) cfg.enabled = false;
    return cfg;
  },

  /** 静音配置 payload（同提醒结构，供原生排闹钟） */
  mutePayload() {
    const cfg = this.muteCfg();
    const sch = Store.active();
    return {
      enabled: cfg.enabled,
      semesterStart: sch ? sch.semesterStart : null,
      periods: sch ? Store.periodsOf(sch) : [],
      courses: sch ? sch.courses.map(c => ({ name: c.name, day: c.day, p1: c.p1, p2: c.p2, weeks: c.weeks || [] })) : [],
    };
  },

  /** 提醒配置（偏好 + 当前课表快照） */
  remCfg() {
    let cfg = {};
    try { cfg = JSON.parse(Store.getPref('reminders', '') || '{}'); } catch (e) {}
    if (cfg.enabled === undefined) cfg.enabled = false;
    if (!cfg.lead) cfg.lead = 10;
    return cfg;
  },

  /** 数据变化后把提醒配置推给 Android 重排闹钟 */
  pushReminders() {
    if (!(window.AndroidBridge && typeof AndroidBridge.setReminders === 'function')) return;
    const cfg = this.remCfg();
    const sch = Store.active();
    if (!sch) cfg.enabled = false;
    const payload = {
      enabled: cfg.enabled,
      lead: cfg.lead,
      semesterStart: sch ? sch.semesterStart : null,
      periods: sch ? Store.periodsOf(sch) : [],
      courses: sch ? sch.courses.map(c => ({ name: c.name, loc: c.loc, day: c.day, p1: c.p1, weeks: c.weeks || [] })) : [],
    };
    const s = JSON.stringify(payload);
    if (s === this._lastRem) return;
    this._lastRem = s;
    AndroidBridge.setReminders(s);
  },

  /** 桌面小组件快照：周次 + 今日课程（Android） */
  pushWidget() {
    if (!(window.AndroidBridge && typeof AndroidBridge.updateWidget === 'function')) return;
    const info = App.todayInfo();
    const now = new Date();
    const snap = {
      title: '哆米的课程表 · 第 ' + App.state.curWeek + ' 周',
      lines: [],
    };
    if (info) {
      snap.title += ' · 周' + '一二三四五六日'[info.day - 1] + ' ' + (now.getMonth() + 1) + '.' + now.getDate();
      for (const c of info.list) {
        const mark = c.status === 'now' ? '▶ ' : c.status === 'done' ? '✓ ' : '';
        snap.lines.push(mark + c.timeStr + ' ' + c.name + (c.loc ? ' ' + c.loc : ''));
      }
    } else {
      snap.title += ' · ' + (now.getMonth() + 1) + '.' + now.getDate();
    }
    // 最近的倒计时（≤14 天）放小组件首行
    if (typeof Countdown !== 'undefined') {
      const cd = Countdown.nearest(14);
      if (cd) snap.lines.unshift('🎯 ' + Countdown.text(cd));
    }
    // 原始课表数据：原生 Worker 每小时/跨天重算小组件内容用
    if (sch) {
      snap.raw = {
        semesterStart: sch.semesterStart || '',
        periods: Store.periodsOf(sch).map(p => ({ start: p.start, end: p.end })),
        courses: sch.courses.map(c => ({ name: c.name, loc: c.loc, day: c.day, p1: c.p1, p2: c.p2, weeks: c.weeks || [] })),
        countdowns: (typeof Countdown !== 'undefined' ? Countdown.list() : []).map(c => ({ name: c.name, date: c.date })),
      };
    }
    const s = JSON.stringify(snap);
    if (s === this._lastWidget) return;
    this._lastWidget = s;
    AndroidBridge.updateWidget(s);
  },

  /** schedule → ICS（RRULE 每周 + EXDATE 掉课周），节次时间用课表自定义时间表 */
  toICS(sch) {
    const L = [];
    const CRLF = '\r\n';
    const pad = (n) => (n < 10 ? '0' + n : '' + n);
    const dt = (date, hhmm) => date.getFullYear() + pad(date.getMonth() + 1) + pad(date.getDate()) + 'T' + hhmm.replace(':', '') + '00';
    const BYDAY = ['MO', 'TU', 'WE', 'TH', 'FR', 'SA', 'SU'];
    const semStart = parseISO(sch.semesterStart);
    const periods = Store.periodsOf(sch);
    const total = Store.totalWeeks();

    L.push('BEGIN:VCALENDAR');
    L.push('VERSION:2.0');
    L.push('PRODID:-//KB CourseSchedule//Export//CN');
    L.push('X-WR-CALNAME:' + sch.name);

    for (const c of sch.courses) {
      const weeks = (c.weeks && c.weeks.length ? c.weeks.slice().sort((a, b) => a - b) : []);
      const allWeeks = !weeks.length;
      const firstW = allWeeks ? 1 : weeks[0];
      const lastW = allWeeks ? Math.min(total, 25) : weeks[weeks.length - 1];
      const monday = addDays(semStart, (firstW - 1) * 7);
      const dayDate = addDays(monday, c.day - 1);
      const untilDate = addDays(semStart, (lastW - 1) * 7 + c.day - 1);

      L.push('BEGIN:VEVENT');
      L.push('UID:' + c.id + '@kbapp');
      L.push('SUMMARY:' + c.name.replace(/[,;\\]/g, ' '));
      if (c.loc) L.push('LOCATION:' + c.loc.replace(/[,;\\]/g, ' '));
      L.push('DTSTART;TZID=Asia/Shanghai:' + dt(dayDate, periods[c.p1 - 1].start));
      L.push('DTEND;TZID=Asia/Shanghai:' + dt(dayDate, periods[c.p2 - 1].end));
      L.push('RRULE:FREQ=WEEKLY;BYDAY=' + BYDAY[c.day - 1] + ';UNTIL=' + dt(untilDate, '23:59') + 'Z');
      if (!allWeeks) {
        const ex = [];
        for (let w = firstW; w <= lastW; w++) {
          if (!weeks.includes(w)) {
            const d = addDays(semStart, (w - 1) * 7 + c.day - 1);
            ex.push('EXDATE;TZID=Asia/Shanghai:' + dt(d, periods[c.p1 - 1].start));
          }
        }
        L.push(...ex);
      }
      L.push('END:VEVENT');
    }
    L.push('END:VCALENDAR');
    return L.join(CRLF);
  },
};

