/* ═══════════ 网格课表解析（教务系统导出格式） ═══════════
 * 特征：课程含「(N-M节)周次/校区:xx/场地:LOC/教师:NAME」标记
 * parseGridOcr：原生 OCR 提供每行坐标 → 星期列按 x 坐标精确还原
 * parseGridText：仅文本（粘贴/无坐标）→ 星期无法定位，置 1 待预览修正
 */
function weeksText(weeks) {
  if (!weeks || !weeks.length) return '';
  const odd = weeks.every(w => w % 2 === 1), even = weeks.every(w => w % 2 === 0);
  if (odd) return '单周';
  if (even) return '双周';
  return toRangeText(weeks).replace(/ 周$/, '');
}

function gridCoursesFromCells(cells) {
  const out = [];
  for (const { pend, cur } of cells) {
    if (!cur.length) continue;
    const first = cur[0];
    const full = ((pend.slice(-3).join('')) + cur.join('')).replace(/\s+/g, '');
    const nameFrags = [];
    for (let i = pend.length - 1; i >= 0; i--) {
      const f = String(pend[i] || '').trim();
      if (!/[/:：]|场地|校区|教师|周|节/.test(f) && f.replace(/[★☆◆■\s]/g, '').length >= 2) nameFrags.unshift(f);
      else break;
    }
    const name = (nameFrags.join('') + first).replace(/[★☆◆■\s]/g, '');
    const pm = full.match(/[（(]\s*(\d{1,2})\s*-\s*(\d{1,2})\s*节/);
    if (!pm || !name) continue;
    const wm = full.match(/(\d{1,2})\s*-\s*(\d{1,2})\s*周(（?\s*单\s*）?|（?\s*双\s*）?)?/);
    let weeks = [];
    if (wm) {
      const odd = (wm[3] || '').indexOf('单') >= 0 ? true : (wm[3] || '').indexOf('双') >= 0 ? false : null;
      for (let w = +wm[1]; w <= +wm[2]; w++)
        if (odd === null || w % 2 === (odd ? 1 : 0)) weeks.push(w);
    }
    const lm = full.match(/场地[:：]([^/]*?)\/?教师[:：](.*)/);
    const loc = lm ? lm[1].replace(/校区[:：]/g, '').replace(/马场道校区/g, '马场道').replace(/[（(]英语专用[)）]/g, '英语专用').trim() : '';
    const teacher = lm ? lm[2].trim() : '';
    out.push({ name, loc, teacher, day: 0, p1: +pm[1], p2: +pm[2], weeks });
  }
  return out;
}

/** 原生 OCR 坐标版：pages = [ [ {t,x,y,w,h}, ... ], ... ] */
function parseGridOcr(pages) {
  const courses = [];
  for (const pageLines of pages) {
    if (!pageLines || !pageLines.length) continue;
    const hdr = pageLines.filter(l => /^星期[一二三四五六日]$/.test((l.t || '').trim()));
    if (hdr.length < 2) continue;
    hdr.sort((a, b) => a.x - b.x);
    const days = '一二三四五六日';
    const bands = hdr.map((h, i) => ({
      day: days.indexOf(h.t.trim().slice(-1)) + 1,
      l: i ? (hdr[i - 1].x + hdr[i - 1].w + h.x) / 2 : -1,
      r: i + 1 < hdr.length ? (hdr[i + 1].x + h.x + h.w) / 2 : 1e9,
    }));
    const cols = {};
    for (const l of pageLines) {
      if (/^星期[一二三四五六日]$/.test((l.t || '').trim())) continue;  // 表头词只用于分列
      const cx = l.x + (l.w || 0) / 2;
      const band = bands.find(b => cx >= b.l && cx < b.r);
      if (!band) continue;
      (cols[band.day] = cols[band.day] || []).push(l);
    }
    for (const dayStr in cols) {
      const ws = cols[dayStr].slice().sort((a, b) => a.y - b.y || a.x - b.x);
      const MARK = /[（(]\s*\d{1,2}\s*-\s*\d{1,2}\s*节/;
      const NAME_MARK = /[★☆◆■]/;
      const cells = []; let cur = null, pend = [];
      for (const w of ws) {
        const isMark = MARK.test(w.t), isName = NAME_MARK.test(w.t);
        const curHasMark = !!cur && cur.some(x => MARK.test(x));
        if (isName || (isMark && curHasMark)) {
          // 新课程开始：pend（可能是跨行课名的上半段）随新单元格走
          if (cur && cur.length) cells.push({ pend: pend.slice(), cur: cur.slice() });
          pend = [];
          cur = [w.t];
        } else if (cur) cur.push(w.t);
        else pend.push(w.t);
      }
      if (cur && cur.length) cells.push({ pend: pend.slice(), cur: cur.slice() });
      for (const c of gridCoursesFromCells(cells)) {
        c.day = +dayStr;
        courses.push(c);
      }
    }
  }
  const seen = new Set();
  return courses.filter(c => {
    const k = c.name + '|' + c.day + '|' + c.p1 + '-' + c.p2;
    if (seen.has(k)) return false; seen.add(k); return true;
  });
}

/** 无坐标版：按记录切分，星期置 1 待预览修正 */
function parseGridText(text) {
  const lines = text.split(/\n+/).map(x => x.trim()).filter(Boolean);
  const MARK = /[（(]\s*\d{1,2}\s*-\s*\d{1,2}\s*节/;
  const cells = []; let cur = null, pend = [];
  const NAME_MARK = /[★☆◆■]/;
  for (const f of lines) {
    if (/★:/.test(f) && f.indexOf('理论') >= 0) continue;
    if (MARK.test(f) || NAME_MARK.test(f)) {
      if (cur && cur.length) cells.push({ pend: pend.slice(), cur: cur.slice() });
      pend = [];
      cur = [f];
    } else if (cur) cur.push(f);
    else pend.push(f);
  }
  if (cur && cur.length) cells.push({ pend: pend.slice(), cur: cur.slice() });
  return gridCoursesFromCells(cells).map(c => Object.assign(c, { day: 1 }));
}

