/* app.js — 启动、全局状态与交互（周次切换 / 详情弹层 / 测试数据入口） */
'use strict';

const App = {
  state: null,

  initState() {
    Store.load();
    const today = new Date();
    const sch = Store.active();
    const semesterStart = sch ? parseISO(sch.semesterStart) : mondayOf(today);
    const curWeek = weekIndexOf(semesterStart, today);
    this.state = {
      today,
      semesterStart,
      viewWeek: Math.max(1, curWeek),
      curWeek,
      weekMonday: addDays(semesterStart, (Math.max(1, curWeek) - 1) * 7),
      rowH: this.measureRowH(),
      periods: Store.periodsOf(sch),
    };
    this.applyTheme();
  },

  /* ── 外观主题（跟随系统/浅色/深色 + 自定义背景色） ── */
  applyTheme() {
    const mode = Store.getPref('theme', 'auto');
    const dark = mode === 'dark' || (mode === 'auto' && window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches);
    document.documentElement.classList.toggle('dark', dark);
    const bg = Store.getPref('bgcolor', '');
    document.documentElement.style.setProperty('--bg', bg || (dark ? '#141922' : '#EDF2FB'));
    const meta = document.querySelector('meta[name="theme-color"]');
    if (meta) meta.setAttribute('content', bg || (dark ? '#141922' : '#EDF2FB'));
    // 顶栏主题按钮图标：随当前生效外观
    const moon = document.getElementById('themeIcoMoon'), sun = document.getElementById('themeIcoSun');
    if (moon && sun) { moon.hidden = !dark; sun.hidden = dark; }
    this.applyGlass();
  },

  /* ── 界面材质：跟随系统 / 清透玻璃 / 磨砂玻璃 / 经典毛玻璃 ── */
  softwareGPU: null,
  detectSoftwareGPU() {
    if (this.softwareGPU !== null) return this.softwareGPU;
    let soft = false;
    try {
      const c = document.createElement('canvas');
      const gl = c.getContext('webgl') || c.getContext('experimental-webgl');
      if (!gl) soft = true;
      else {
        const ext = gl.getExtension('WEBGL_debug_renderer_info');
        const r = ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER);
        soft = /swiftshader|software|basic render|llvmpipe/i.test(String(r));
      }
    } catch (e) { soft = false; }
    this.softwareGPU = soft;
    return soft;
  },

  applyGlass() {
    const mat = Store.getPref('material', '') || Store.getPref('glass', 'auto'); // 兼容旧偏好
    const de = document.documentElement;
    let noGlass = false, frost = false;
    if (mat === 'off' || mat === 'classic') noGlass = true;
    else if (mat === 'frost') frost = true;
    else if ((mat === 'auto' || mat === 'on') && this.detectSoftwareGPU()) noGlass = true;
    de.classList.toggle('no-glass', noGlass);
    de.classList.toggle('m-frost', frost && !noGlass);
    de.classList.toggle('m-classic', noGlass);
  },

  /* ── 视图与 Tab ── */
  viewOrder: ['today', 'timeline', 'grid'],

  positionThumb() {
    const seg = document.getElementById('viewSeg'), th = document.getElementById('viewSegThumb');
    const on = seg && seg.querySelector('button.on');
    if (th && on) { th.style.width = on.offsetWidth + 'px'; th.style.transform = 'translateX(' + on.offsetLeft + 'px)'; }
    const tb = document.getElementById('tabbar'), tt = document.getElementById('tabThumb');
    const onb = tb && tb.querySelector('button.on');
    if (tt && onb) { tt.style.width = onb.offsetWidth + 'px'; tt.style.transform = 'translateX(' + onb.offsetLeft + 'px)'; }
  },

  setView(v, animate) {
    const prev = Store.getPref('lastView', 'today');
    Store.setPref('lastView', v);
    for (const b of document.querySelectorAll('#viewSeg button')) b.classList.toggle('on', b.dataset.v === v);
    document.getElementById('vwToday').hidden = v !== 'today';
    document.getElementById('vwTimeline').hidden = v !== 'timeline';
    document.getElementById('vwGrid').hidden = v !== 'grid';
    this.positionThumb();
    // 方向感知的切换动画
    const el = document.getElementById('vw' + v[0].toUpperCase() + v.slice(1));
    if (el && animate && prev !== v) {
      const cls = this.viewOrder.indexOf(v) > this.viewOrder.indexOf(prev) ? 'anim-r' : 'anim-l';
      el.classList.remove('anim-r', 'anim-l'); void el.offsetWidth;
      el.classList.add(cls);
      el.addEventListener('animationend', () => el.classList.remove(cls), { once: true });
    }
    // 网格内容延后一帧渲染：先保证滑块与淡入动画满帧
    if (v === 'grid') setTimeout(() => { if (Store.getPref('lastView') === v) this.refresh(); }, 240);
  },

  setTab(t, animate) {
    const prev = Store.getPref('lastTab', 'timetable');
    Store.setPref('lastTab', t);
    for (const b of document.querySelectorAll('#tabbar button')) b.classList.toggle('on', b.dataset.tab === t);
    document.getElementById('viewTimetable').hidden = t !== 'timetable';
    document.getElementById('viewStats').hidden = t !== 'stats';
    document.getElementById('viewMe').hidden = t !== 'me';
    this.positionThumb();
    const el = document.getElementById('view' + t[0].toUpperCase() + t.slice(1));
    if (el && animate && prev !== t) {
      el.classList.remove('anim-tab'); void el.offsetWidth;
      el.classList.add('anim-tab');
      el.addEventListener('animationend', () => el.classList.remove('anim-tab'), { once: true });
    }
    if (t === 'stats' && typeof Extras !== 'undefined') Extras.renderStatsView();
    if (t === 'me' && typeof Schedules !== 'undefined') Schedules.renderMe();
    if (t === 'timetable') this.refresh();
  },

  /** 课表页内横滑：Today ⇄ 时间线 ⇄ 周网格 */
  swipeView(dir) {
    const cur = Store.getPref('lastView', 'today');
    const i = this.viewOrder.indexOf(cur) + dir;
    if (i >= 0 && i < this.viewOrder.length) this.setView(this.viewOrder[i], true);
  },

  /* ── 分钟级自动刷新：跨节/跨天保持状态新鲜 ── */
  startTicker() {
    if (this._ticker) clearInterval(this._ticker);
    this._ticker = setInterval(() => this.tick(), 30000);
  },

  tick() {
    const now = new Date();
    if (!sameDay(this.state.today, now)) {
      this.initState();          // 跨天：整页重算（周次/今日列表/小组件）
      this.refresh();
      return;
    }
    const nowMin = now.getHours() * 60 + now.getMinutes();
    if (this._lastMin === nowMin) return;
    this._lastMin = nowMin;
    this.state.today = now;      // 同一天：只刷新时间敏感的部分
    this.renderView();
    if (typeof Schedules !== 'undefined' && Schedules.pushWidget) { try { Schedules.pushWidget(); } catch (e) {} }
  },

  /** 按子视图轻量刷新时间敏感内容 */
  renderView() {
    this.state.rowH = this.measureRowH();
    Render.renderTodayView(this.state);
    Render.renderTimeline(this.state);
    Render.renderTimeCol(this.state);
  },

  /* ── 返回键：弹层入历史栈，系统返回关闭最上层 ── */
  overlays: [],
  trackOverlay(closeFn) {
    const self = this;
    const rec = {
      done: false,
      closeFn,
      close() {
        if (rec.done) return;
        rec.done = true;
        const i = self.overlays.indexOf(rec);
        if (i >= 0) self.overlays.splice(i, 1);
        closeFn();
        try { history.back(); } catch (e) {}
      },
    };
    this.overlays.push(rec);
    try { history.pushState({ kbO: this.overlays.length }, ''); } catch (e) {}
    return rec;
  },

  /* ── 顶栏主题按钮：跟随系统 → 深色 → 浅色 循环 ── */
  cycleTheme() {
    const order = ['auto', 'dark', 'light'];
    const cur = Store.getPref('theme', 'auto');
    const next = order[(order.indexOf(cur) + 1) % order.length];
    Store.setPref('theme', next);
    this.applyTheme();
    toast(next === 'auto' ? '深色模式：跟随系统' : next === 'dark' ? '深色模式：开' : '深色模式：关', 'ok');
  },

  /* ── 今日视图数据：今日课程 + 当前/下一节 ── */
  todayInfo() {
    const sch = Store.active();
    if (!sch) return null;
    const now = new Date();
    const day = (now.getDay() + 6) % 7 + 1;
    const week = this.state.curWeek;
    const nowMin = now.getHours() * 60 + now.getMinutes();
    const periods = Store.periodsOf(sch);
    const list = sch.courses
      .filter(c => c.day === day && (!c.weeks || !c.weeks.length || c.weeks.includes(week)))
      .slice()
      .sort((a, b) => a.p1 - b.p1 || a.p2 - b.p2)
      .map(c => {
        const ps = periods[c.p1 - 1], pe = periods[c.p2 - 1];
        const s = minutesOf(ps.start), e = minutesOf(pe.end);
        return Object.assign({}, c, {
          timeStr: ps.start, endStr: pe.end,
          status: nowMin < s ? 'todo' : (nowMin <= e ? 'now' : 'done'),
          minsToStart: s - nowMin,
        });
      });
    const nowCourse = list.find(c => c.status === 'now') || null;
    const nextCourse = list.find(c => c.status === 'todo') || null;
    return { list, nowCourse, nextCourse, day, week };
  },

  measureRowH() {
    const h = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--row-h'));
    return isNaN(h) ? 62 : h;
  },

  /** 切到第 N 周（1 起） */
  setWeek(n) {
    const total = Store.totalWeeks();
    n = Math.max(1, Math.min(total, n));
    this.state.viewWeek = n;
    this.state.weekMonday = addDays(this.state.semesterStart, (n - 1) * 7);
    this.refresh();
  },

  refresh() {
    Render.renderAll(this.state);
    // 提醒/小组件配置随课表变化同步给 Android
    if (typeof Schedules !== 'undefined') {
      try {
        if (Schedules.pushReminders) Schedules.pushReminders();
        if (Schedules.pushWidget) Schedules.pushWidget();
      } catch (e) { /* 非 Android 环境忽略 */ }
    }
  },

  /* ── 周次选择浮层 ── */
  toggleWeekPicker() {
    const el = document.getElementById('weekPicker');
    if (!el.hidden) { el.hidden = true; return; }
    const total = Store.totalWeeks();
    let html = '';
    if (this.state.viewWeek !== this.state.curWeek) {
      html += '<button class="wp-item wp-back" id="wpBack">↩ 回到本周（第 ' + this.state.curWeek + ' 周）</button>';
    }
    for (let w = 1; w <= total; w++) {
      const mon = addDays(this.state.semesterStart, (w - 1) * 7);
      const sun = addDays(mon, 6);
      html += '<button class="wp-item' + (w === this.state.viewWeek ? ' active' : '') + '" data-w="' + w + '">' +
        '第 ' + w + ' 周' +
        '<small>' + (mon.getMonth() + 1) + '.' + mon.getDate() + ' - ' + (sun.getMonth() + 1) + '.' + sun.getDate() + '</small></button>';
    }
    el.innerHTML = html;
    el.hidden = false;
    el.scrollTop = el.querySelector('.wp-item.active') ? el.querySelector('.wp-item.active').offsetTop - 100 : 0;
    for (const b of el.querySelectorAll('.wp-item[data-w]')) {
      b.addEventListener('click', () => { el.hidden = true; App.setWeek(+b.dataset.w); });
    }
    const back = el.querySelector('#wpBack');
    if (back) back.addEventListener('click', () => { el.hidden = true; App.setWeek(App.state.curWeek); });
  },

  /* ── 测试数据（?test=1 时注入）：孔思丹 2026-2027-1 真实课表 ── */
  loadTestCourses() {
    const mk = (name, loc, teacher, day, p1, p2, weeks) =>
      ({ id: uid(), name, loc, teacher, day, p1, p2, weeks: weeks || [], color: Store.colorFor(name) });
    const w = (a, b) => { const r = []; for (let i = a; i <= b; i++) r.push(i); return r; };
    const odd = (a, b) => { const r = []; for (let i = a; i <= b; i++) if (i % 2) r.push(i); return r; };
    const courses = [
      mk('中级口译1', 'E406（英语专用）', '宋晓冬', 1, 3, 4, w(1, 17)),
      mk('英语口译实战', 'M1102', '宋晓冬', 1, 12, 13, w(1, 17)),
      mk('习近平新时代中国特色社会主义思想概论', 'W104', '郑海军', 2, 1, 2, w(1, 17)),
      mk('高级英语1', 'M412', '黄志军', 2, 3, 4, w(1, 17)),
      mk('高级英语1', 'M412', '黄志军', 3, 1, 2, w(1, 17)),
      mk('二外西语3', 'E202', '王洋力', 3, 3, 4, w(1, 17)),
      mk('英汉翻译', 'M403', '雷芳', 4, 1, 2, w(1, 17)),
      mk('语言学概论', 'W105', '李云靖', 4, 7, 8, odd(1, 17)),
      mk('汉英翻译', 'M406', '张虹', 5, 1, 2, w(1, 17)),
      mk('中国文化概要', 'W304', '刘春梅', 5, 3, 4, w(1, 17)),
      mk('科技英语阅读', 'E204', '李云靖', 5, 7, 8, w(1, 17)),
      mk('创业基础与就业指导', 'W104', '李宗琪', 5, 9, 10, odd(3, 9)),
      mk('创业基础与就业指导', 'W104', '陈曌', 5, 9, 10, odd(11, 17)),
    ];
    const sch = Store.addSchedule('孔思丹 · 2026-2027-1', courses, '2026-08-31');
    Store.setActive(sch.id);
    App.initStateKeepWeek();
  },

  initStateKeepWeek() {
    const old = this.state;
    this.initState();
    if (old) {
      // 保留"相对当前周的偏移"（如导入课表后开学日变化，绝对周数意义会变）
      const delta = old.viewWeek - old.curWeek;
      this.setWeek(Math.max(1, this.state.curWeek + delta));
    } else this.refresh();
  },

  boot() {
    Store.load();
    this.initState();
    this.refresh();

    // 注意：import.js 等模块用 const 声明，不挂 window，需用 typeof 守卫
    if (typeof Importer !== 'undefined' && Importer.init) Importer.init();
    if (typeof OcrImporter !== 'undefined' && OcrImporter.init) OcrImporter.init();
    if (typeof Schedules !== 'undefined') Schedules.init();

    // 视图分段 + 底部 Tab（带滑动指示器与切换动画）
    for (const b of document.querySelectorAll('#viewSeg button')) {
      b.addEventListener('click', () => this.setView(b.dataset.v, true));
    }
    for (const b of document.querySelectorAll('#tabbar button')) {
      b.addEventListener('click', () => this.setTab(b.dataset.tab, true));
    }
    this.setView(Store.getPref('lastView', 'today'));
    this.setTab(Store.getPref('lastTab', 'timetable'));
    requestAnimationFrame(() => this.positionThumb());
    window.addEventListener('resize', () => this.positionThumb());
    document.fonts && document.fonts.ready && document.fonts.ready.then(() => this.positionThumb());

    // 课表页横滑切换视图（Today ⇄ 时间线 ⇄ 周网格；周网格内的横滑保留为切周）
    let vsx = null, vsy = null;
    const tt = document.getElementById('viewTimetable');
    tt.addEventListener('touchstart', (e) => { vsx = e.touches[0].clientX; vsy = e.touches[0].clientY; }, { passive: true });
    tt.addEventListener('touchend', (e) => {
      if (vsx === null) return;
      const dx = e.changedTouches[0].clientX - vsx, dy = e.changedTouches[0].clientY - vsy;
      if (Store.getPref('lastView', 'today') !== 'grid' && Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5) {
        this.swipeView(dx < 0 ? 1 : -1);
      }
      vsx = vsy = null;
    }, { passive: true });

    // 周次行 → 周选择器
    document.getElementById('weekLine').addEventListener('click', () => this.toggleWeekPicker());
    document.addEventListener('click', (e) => {
      const el = document.getElementById('weekPicker');
      if (!el.hidden && !el.contains(e.target) && !e.target.closest('#weekLine')) el.hidden = true;
    });

    // 左右滑动切周（仅周网格视图）
    let sx = null, sy = null;
    const grid = document.getElementById('gridScroll');
    grid.addEventListener('touchstart', (e) => { sx = e.touches[0].clientX; sy = e.touches[0].clientY; }, { passive: true });
    grid.addEventListener('touchend', (e) => {
      if (sx === null) return;
      const dx = e.changedTouches[0].clientX - sx, dy = e.changedTouches[0].clientY - sy;
      if (Store.getPref('lastView', 'today') === 'grid' && Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5) this.setWeek(this.state.viewWeek + (dx < 0 ? 1 : -1));
      sx = sy = null;
    }, { passive: true });

    // 空状态导入按钮
    document.getElementById('emptyImportBtn').addEventListener('click', () => {
      if (typeof Importer !== 'undefined' && Importer.pick) Importer.pick();
    });
    document.getElementById('emptyOcrBtn').addEventListener('click', () => {
      if (typeof OcrImporter !== 'undefined' && OcrImporter.pick) OcrImporter.pick();
    });
    document.getElementById('emptyTextBtn').addEventListener('click', () => {
      if (typeof TextImport !== 'undefined') TextImport.open();
    });
    document.getElementById('emptyManualBtn').addEventListener('click', () => CourseEditor.open());
    document.getElementById('btnOcr').addEventListener('click', () => OcrImporter.pick());

    // 回到本周胶囊
    document.getElementById('nowWeekPill').addEventListener('click', () => this.setWeek(this.state.curWeek));

    // 顶栏主题快捷切换；齿轮 → 我的
    document.getElementById('btnTheme').addEventListener('click', () => this.cycleTheme());
    document.getElementById('btnSettings').addEventListener('click', () => this.setTab('me'));

    // 系统返回键：关闭最上层弹层（详见 trackOverlay）
    window.addEventListener('popstate', () => {
      const rec = this.overlays.pop();
      if (rec) { rec.done = true; rec.closeFn(); }
    });

    // 分钟级自动刷新
    this.startTicker();

    // 系统深色模式变化时刷新主题
    if (window.matchMedia) {
      try {
        matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => this.applyTheme());
      } catch (e) { /* 旧浏览器忽略 */ }
    }

    // 点空白格子 → 快捷添加（带星期默认值）；点卡片不触发
    document.getElementById('daysGrid').addEventListener('click', (e) => {
      const col = e.target.closest('.day-col');
      if (!col || e.target !== col) return;
      if (e.target.closest('.course')) return;
      if (!Store.active()) return;
      CourseEditor.open(null, { day: +col.dataset.day });
    });

    // 测试数据入口
    if (new URLSearchParams(location.search).get('test') === '1') {
      localStorage.removeItem(Store.KEY);
      this.loadTestCourses();
    }
  },
};

document.addEventListener('DOMContentLoaded', () => App.boot());

// PWA：仅在 http(s) 环境注册 Service Worker（file:// 下优雅降级）
if ('serviceWorker' in navigator && /^https?:$/.test(location.protocol)) {
  navigator.serviceWorker.register('sw.js').then((reg) => {
    // 新版本 SW 激活后刷新一次，避免旧缓存资源（升级 APK 后首次启动）
    reg.addEventListener('updatefound', () => {
      const nw = reg.installing;
      if (!nw) return;
      nw.addEventListener('statechange', () => {
        if (nw.state === 'activated' && navigator.serviceWorker.controller) location.reload();
      });
    });
  }).catch((e) => console.warn('SW register failed', e));
}

