/* share.js — 课表分享长图：canvas 2D 手绘当前周视图 → PNG
 * Android：AndroidBridge.shareImage(fileName, base64) → 存相册/系统分享
 * 桌面：blob 下载
 */
'use strict';

const ShareCard = {
  /* 浅色主题配色（分享图始终用浅色，保证可读性） */
  PAL: [
    ['#DCE8C5', '#A9C97E'], ['#F8DFC4', '#E8A96F'], ['#DDD6F5', '#9D8FE0'],
    ['#F9D9DC', '#E89AA6'], ['#FAE7BD', '#E5C25A'], ['#C9E4F6', '#7FB8E0'],
    ['#CDE8DC', '#7FC4A4'], ['#D6DAEC', '#96A0CC'],
  ],
  INK: '#46443F', LOC: '#8B887F', BG: '#F7F5F1', BLUE: '#3D7BF7', GRAY: '#B9B6AD',

  export() {
    const sch = Store.active();
    if (!sch) { toast('还没有可分享的课表', 'err'); return; }
    const canvas = this.draw(sch);
    const fileName = sch.name.replace(/[\\/:*?"<>|]/g, '_') + '-第' + App.state.viewWeek + '周.png';
    if (window.AndroidBridge && typeof AndroidBridge.shareImage === 'function') {
      canvas.toBlob((blob) => {
        const reader = new FileReader();
        reader.onload = () => AndroidBridge.shareImage(fileName, reader.result.split(',')[1]);
        reader.readAsDataURL(blob);
      }, 'image/png');
      return;
    }
    try {
      const a = document.createElement('a');
      a.href = canvas.toDataURL('image/png');
      a.download = fileName;
      document.body.appendChild(a); a.click(); a.remove();
      toast('长图已生成', 'ok');
    } catch (e) { console.error(e); toast('分享失败', 'err'); }
  },

  draw(sch) {
    const W = 900, PAD = 30, TIME_W = 130;
    const ROW_H = 200, HEADER_H = 210, WEEKBAR_H = 90, FOOTER_H = 120;
    const viewWeek = App.state.viewWeek;
    const semStart = App.state.semesterStart;
    const monday = addDays(semStart, (viewWeek - 1) * 7);
    const gridW = W - PAD * 2 - TIME_W;
    const colW = gridW / 7;
    const H = HEADER_H + WEEKBAR_H + ROW_H * PERIODS.length + FOOTER_H;

    const canvas = document.createElement('canvas');
    canvas.width = W; canvas.height = H;
    const ctx = canvas.getContext('2d');

    // 背景
    ctx.fillStyle = this.BG;
    ctx.fillRect(0, 0, W, H);

    // ── 标题区（超宽省略，给右侧品牌留位） ──
    ctx.fillStyle = '#2E2D2A';
    ctx.font = '700 52px -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif';
    ctx.textBaseline = 'alphabetic';
    let title = sch.name;
    const brand = '哆米的课程表';
    const maxTitle = W - PAD * 2 - ctx.measureText(brand).width - 40;
    while (title.length > 2 && ctx.measureText(title + '…').width > maxTitle) title = title.slice(0, -1);
    if (title !== sch.name) title += '…';
    ctx.fillText(title, PAD, 96);
    const sun = addDays(monday, 6);
    ctx.fillStyle = this.GRAY;
    ctx.font = '500 30px -apple-system, "PingFang SC", sans-serif';
    ctx.fillText('第 ' + viewWeek + ' 周 · ' + (monday.getMonth() + 1) + '.' + monday.getDate() +
      ' - ' + (sun.getMonth() + 1) + '.' + sun.getDate(), PAD, 152);
    ctx.fillStyle = this.BLUE;
    ctx.font = '700 34px -apple-system, "PingFang SC", sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(brand, W - PAD, 96);
    ctx.textAlign = 'left';

    const gridX = PAD + TIME_W;
    const weekTop = HEADER_H;

    // ── 星期表头 ──
    const todayWeekday = sameDay(mondayOf(new Date()), monday) ? (new Date().getDay() + 6) % 7 : -1;
    const WD = ['周一', '周二', '周三', '周四', '周五', '周六', '周日'];
    ctx.textAlign = 'center';
    for (let i = 0; i < 7; i++) {
      const cx = gridX + colW * i + colW / 2;
      const d = addDays(monday, i);
      const isToday = i === todayWeekday;
      ctx.fillStyle = isToday ? this.BLUE : (i >= 5 ? this.GRAY : '#8E8C85');
      ctx.font = (isToday ? '700 ' : '500 ') + '26px -apple-system, "PingFang SC", sans-serif';
      ctx.fillText(WD[i], cx, weekTop + 30);
      if (isToday) {
        ctx.beginPath();
        ctx.arc(cx, weekTop + 64, 22, 0, Math.PI * 2);
        ctx.fillStyle = this.BLUE; ctx.fill();
        ctx.fillStyle = '#fff';
      } else {
        ctx.fillStyle = i >= 5 ? this.GRAY : '#6B6963';
      }
      ctx.font = '500 26px -apple-system, "PingFang SC", sans-serif';
      ctx.fillText(String(d.getDate()), cx, weekTop + 73);
    }
    ctx.textAlign = 'left';

    // ── 时间轴 ──
    const gridTop = weekTop + WEEKBAR_H;
    const periods = Store.periodsOf(sch);
    for (const p of periods) {
      const top = gridTop + (p.n - 1) * ROW_H;
      ctx.textAlign = 'center';
      ctx.fillStyle = '#4C4A45';
      ctx.font = '700 30px -apple-system, "PingFang SC", sans-serif';
      ctx.fillText(String(p.n), PAD + TIME_W / 2 - 10, top + ROW_H / 2 - 14);
      ctx.fillStyle = this.GRAY;
      ctx.font = '400 19px -apple-system, "PingFang SC", sans-serif';
      ctx.fillText(p.start, PAD + TIME_W / 2 - 10, top + ROW_H / 2 + 18);
      ctx.fillText(p.end, PAD + TIME_W / 2 - 10, top + ROW_H / 2 + 44);
    }
    ctx.textAlign = 'left';

    // ── 课程卡片（含冲突并排） ──
    const byDay = {};
    for (let d = 1; d <= 7; d++) byDay[d] = [];
    for (const c of sch.courses) {
      if (!c.weeks || !c.weeks.length || c.weeks.includes(viewWeek)) byDay[c.day].push(c);
    }
    for (let day = 1; day <= 7; day++) {
      const sorted = byDay[day].slice().sort((a, b) => a.p1 - b.p1 || a.p2 - b.p2);
      const groups = [];
      for (const c of sorted) {
        const g = groups.find(grp => grp.some(x => c.p1 <= x.p2 && x.p1 <= c.p2));
        if (g) g.push(c); else groups.push([c]);
      }
      for (const g of groups) {
        const n = g.length;
        g.forEach((c, idx) => {
          const x0 = gridX + colW * (day - 1) + (colW * idx / n) + 4;
          const w = colW / n - 8;
          const y0 = gridTop + (c.p1 - 1) * ROW_H + 6;
          const h = (c.p2 - c.p1 + 1) * ROW_H - 12;
          const pal = this.PAL[c.color % this.PAL.length];
          this.roundRect(ctx, x0, y0, w, h, 16);
          ctx.fillStyle = pal[0]; ctx.fill();
          // 顶部小横条
          ctx.fillStyle = pal[1];
          this.roundRect(ctx, x0 + w / 2 - w * 0.29, y0 + 14, w * 0.58, 8, 4);
          ctx.fill();
          // 文本
          ctx.fillStyle = this.INK;
          ctx.font = '700 24px -apple-system, "PingFang SC", sans-serif';
          this.wrapText(ctx, c.name, x0 + 10, y0 + 52, w - 20, 30, Math.max(2, Math.floor((h - 80) / 30)));
          const locY = y0 + 52 + this.lastWrapLines * 30 + 8;
          if (c.loc && locY + 20 < y0 + h - 8) {
            ctx.fillStyle = pal[1];
            ctx.font = '500 17px -apple-system, "PingFang SC", sans-serif';
            this.wrapText(ctx, c.loc, x0 + 8, locY, w - 16, 20, 3);
          }
        });
      }
    }

    // ── 页脚 ──
    ctx.fillStyle = this.GRAY;
    ctx.font = '500 24px -apple-system, "PingFang SC", sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('哆米的课程表 · 本地优先 · 无广告', W / 2, H - 46);
    ctx.textAlign = 'left';
    return canvas;
  },

  roundRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    if (ctx.roundRect) { ctx.roundRect(x, y, w, h, r); return; }
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  },

  lastWrapLines: 2,

  wrapText(ctx, text, x, y, maxW, lineH, maxLines) {
    let line = '', lines = 0;
    for (const ch of String(text)) {
      // 闭合标点永远挂在前一行行尾，不单独成行
      if (line && /^[)）\]】。，；、！？%°]$/.test(ch)) { line += ch; continue; }
      if (ctx.measureText(line + ch).width > maxW && line) {
        // 不拆字母/数字串
        if (/[\w]$/.test(line) && /^[\w]$/.test(ch)) { line += ch; continue; }
        lines++;
        if (lines >= maxLines) {
          ctx.fillText(line.slice(0, -1) + '…', x, y);
          this.lastWrapLines = maxLines;
          return;
        }
        ctx.fillText(line, x, y);
        y += lineH;
        line = ch;
      } else line += ch;
    }
    if (line) { ctx.fillText(line, x, y); lines++; }
    this.lastWrapLines = Math.max(1, lines);
  },
};
